window.__detail("2026-10-31",[{"id":"2026-10-31-1","date":"2026-10-31","tag":"판매채널","title":"보험 97%를 창구에서 판 농협생명, 내년 3월 특례가 끝나면?","predict":{"q":"NH농협생명이 올해 1~8월 새로 받은 첫 보험료 가운데 은행·농축협 창구(방카슈랑스)에서 나온 비중은 얼마일까요?","options":["약 95%","97% 이상","약 90%"],"answer":1,"reveal":"**97.3%**예요. 1조 694억 원 가운데 1조 402억 원이 방카슈랑스에서 나왔어요. 그런데 이 판매를 떠받쳐 온 **농·축협 판매 특례가 2027년 3월 1일 끝나요**."},"comic":{"title":"창구가 전부였는데","panels":[{"caption":"판매 실적 회의","bg":"meeting","board":"up","sign":"방카슈랑스 97.3%","chars":[{"who":"insurer","mood":"happy","pose":"cheer","fx":"sparkle","say":"창구에서 거의 다 팔렸어요!"}]},{"caption":"그런데 달력을 보니","bg":"focus","sign":"특례 만료 2027년 3월 1일","chars":[{"who":"regulator","mood":"thinking","pose":"doc","say":"한 회사 상품은 25%까지예요"},{"who":"insurer","mood":"surprised","fx":"exclaim"}]},{"caption":"다른 판매 길은?","bg":"office","sign":"연장 법안 2건 계류","chars":[{"who":"insurer","mood":"worried","pose":"worry","say":"다른 길이 거의 없는데…"},{"who":"mango","mood":"thinking","pose":"think","say":"국회 결정을 봐야 해요"}]},{"caption":"망고 계리사의 정리","bg":"office","chars":[{"who":"mango","mood":"happy","pose":"point","fx":"idea","say":"판매 길이 바뀌면 가정도 바뀌어요"},{"who":"onion","mood":"thinking","pose":"think","say":"창구 따라 상품도 달라지겠네"}]}]},"numbers":[{"label":"첫 보험료 중 방카슈랑스","value":"97.3%","note":"올해 1~8월, 1조 694억 원 중 1조 402억 원"},{"label":"3분기 누적 순이익","value":"68억 원","note":"작년보다 96.8% 감소"},{"label":"누적 신계약 보험계약마진","value":"8,471억 원","note":"작년 4,334억 원의 두 배 가까이"},{"label":"농·축협 판매 특례 만료","value":"2027.3.1","note":"연장 법안 2건 국회 계류"}],"points":["은행·농축협 같은 금융기관보험대리점은 원래 **한 보험사 상품을 신규 모집액의 25%를 넘겨 팔 수 없어요**. 자산 2조 원 미만 지역 농·축협은 2012년부터 특례로 이 규제를 유예받아 농협보험 상품만 팔아 왔고, 2016년과 2021년 두 번 연장됐어요.","농협생명은 3분기에만 282억 원 순손실을 냈고, 누적 투자손익은 −1,021억 원으로 적자로 돌아섰어요. 보험손익도 1,966억 원으로 35.8% 줄었는데, 계리감독 선진화에 따른 **손실계약 비용 증가와 사업비 가정 변경**이 원인으로 꼽혔어요.","반면 신계약 보험계약마진은 8,471억 원으로 두 배 가까이 늘었고, 보유 보험계약마진도 4조 9,762억 원으로 16.4% 늘었어요."],"why":"판매채널은 영업만의 문제가 아니에요. 어디서 누구에게 파느냐에 따라 **가입자 특성, 해지율, 사업비가 달라지기 때문에** 계리가정과 상품 설계도 함께 바뀔 수 있어요. 한 채널에 97%를 기대는 회사라면, 규제 하나로 신계약 규모가 크게 흔들릴 수 있다는 점이 핵심이에요. 이런 뉴스를 볼 땐 \"이 회사의 판매 구조가 바뀌면 숫자 가정 중 무엇이 먼저 흔들릴까?\"를 생각해보세요.","chain":["금융기관보험대리점은 한 보험사 상품을 25%까지만 팔 수 있음","지역 농·축협은 특례로 농협보험 상품만 판매해 옴","농협생명 첫 보험료의 97.3%가 방카슈랑스에서 나옴","특례가 2027년 3월 1일 끝나면 판매 비중 제한이 적용될 수 있음","신계약 규모와 판매채널 구성이 바뀔 수 있음","판매채널이 바뀌면 해지율·사업비 가정과 상품 전략도 다시 봐야 함"],"role":{"q":"당신은 NH농협생명 상품개발팀 신입이에요. 팀장님이 묻습니다. \"특례가 연장되지 않으면 우리 상품 전략에서 무엇부터 다시 봐야 할까?\" 생각을 정리해보세요.","model":"가장 먼저 **판매채널 구성이 바뀌는 상황**을 가정해야 해요. 지금은 첫 보험료의 97.3%가 방카슈랑스에서 나오는데, 25% 규제가 적용되면 농·축협 창구에서 다른 회사 상품도 함께 팔리게 될 수 있어요. 그러면 창구에서 경쟁력 있는 상품, 예를 들어 보험료나 보장 구성이 비교에서 밀리지 않는 상품이 필요해요. 또 다른 채널을 키우면 가입자 특성과 해지율, 모집 수수료 같은 사업비가 지금과 달라질 수 있어서 **계리가정도 채널별로 따로 점검**해야 해요. 다만 국회에 연장 법안 2건이 계류 중이라, 연장될 때와 안 될 때를 나눠 준비하는 게 현실적이에요."},"summary":"농협생명은 보험을 거의 다 농협 창구에서 팔았는데, 그걸 가능하게 한 특별 규칙이 내년 3월에 끝날 수 있어서 판매 길을 고민해야 해.","interview":{"q":"NH농협생명에 지원했다면, 회사가 마주한 가장 큰 과제는 무엇이라고 보나요?","guide":"결론부터: 방카슈랑스에 크게 기대는 판매 구조와 2027년 3월 특례 만료가 가장 큰 과제라고 말해요.\n근거: 올해 1~8월 첫 보험료의 97.3%가 방카슈랑스에서 나왔고, 특례가 끝나면 한 회사 상품을 25%까지만 파는 규제가 적용될 수 있어요.\n관점: 상품개발·계리 관점에서는 채널이 바뀌면 해지율·사업비 가정과 상품 경쟁력이 달라지니, 채널별 가정을 미리 점검해야 한다고 덧붙여요.\n마무리: 신계약 보험계약마진이 두 배 가까이 늘어난 성장세를 지키면서 채널을 다변화하는 데 기여하고 싶다고 마무리해요."},"quiz":[{"q":"금융기관보험대리점의 '25% 규제'는 무엇을 제한할까?","o":["보험 판매 수수료를 신규 모집액의 25%까지만 받는 것","한 보험사 상품을 신규 모집액의 25%를 넘겨 파는 것","창구 직원의 25%를 넘겨 보험 판매에 배치하는 것"],"a":1,"e":"은행이나 농축협 창구가 한 보험사 상품만 몰아 팔지 못하게 신규 모집액의 25%로 묶는 규제예요."},{"q":"농협생명의 3분기 누적 순이익이 크게 줄었는데도 앞으로의 이익 바탕이 커졌다고 볼 수 있는 지표는?","o":["투자손익","보험손익","신계약 보험계약마진"],"a":2,"e":"신계약 보험계약마진이 8,471억 원으로 두 배 가까이 늘어, 앞으로 나눠서 인식할 이익이 쌓였어요."},{"q":"판매채널이 바뀔 때 계리가정에서 함께 점검해야 할 것으로 가장 알맞은 것은?","o":["금리 전망과 할인율","회계기준과 감독규정","해지율과 사업비"],"a":2,"deep":true,"e":"채널마다 가입자 특성과 수수료 구조가 달라서 해지율과 사업비 가정이 달라질 수 있어요."}],"terms":[{"t":"방카슈랑스","d":"은행 창구에서 보험상품을 파는 판매 방식이에요."},{"t":"25% 룰","d":"은행 같은 금융기관보험대리점이 한 보험사 상품을 신규 모집액의 25%를 넘겨 팔지 못하게 하는 규제예요."},{"t":"농·축협 판매 특례","d":"자산 2조 원 미만 지역 농·축협이 25% 규제를 유예받아 농협보험 상품만 팔 수 있게 한 예외예요. 2012년에 생겨 두 번 연장됐어요."},{"t":"보험계약마진","d":"보험계약에서 앞으로 나눠서 이익으로 인식할, 아직 실현되지 않은 이익이에요."},{"t":"손실계약","d":"앞으로 받을 보험료보다 나갈 보험금과 비용이 더 커서, 처음부터 손실이 예상되는 보험계약이에요."}],"thread":{"id":"sales-channel","name":"판매채널과 수수료"},"jobs":["영업·채널","상품개발","계리"],"companies":["NH농협생명"],"figs":[{"type":"bars","title":"농협생명 첫 보험료 중 방카슈랑스 비중","unit":"%","items":[{"label":"2024년","value":96.8},{"label":"2025년","value":96.9},{"label":"2026년","value":97.3,"hi":true}],"note":"2026년은 1~8월 기준이에요. 해마다 조금씩 더 높아졌어요.","look":"방카슈랑스 비중이 96.8%에서 97.3%로 해마다 조금씩 높아졌어요."},{"type":"timeline","title":"농·축협 판매 특례의 흐름","items":[{"when":"2012년","label":"농협생명·농협손해보험 출범과 함께 특례 도입"},{"when":"2016년","label":"첫 번째 연장"},{"when":"2021년","label":"두 번째 연장"},{"when":"2026년 7월","label":"특례 연장 법안 2건 국회 발의"},{"when":"2026년 10월","label":"3분기 실적 발표, 방카슈랑스 비중 97.3%","now":true},{"when":"2027년 3월 1일","label":"특례 만료 예정"}],"look":"2012년 도입된 특례가 두 번 연장됐고 2027년 3월 1일 끝나요."}],"sources":[{"name":"허프포스트코리아","url":"https://www.huffingtonpost.kr/article/261659"}],"brief":{"what":"NH농협생명은 올해 1~8월 첫 보험료의 **97.3%**를 은행·농축협 창구에서 받았는데, 이를 떠받친 농·축협 판매 특례가 2027년 3월 1일 끝나요.","why":"금융기관보험대리점은 한 보험사 상품을 신규 모집액의 25%까지만 팔 수 있는데, 지역 농·축협은 2012년부터 특례로 이 규제를 유예받아 왔기 때문이에요.","so":"특례가 연장되지 않으면 판매채널 구성이 바뀔 수 있어서, 채널별 해지율·사업비 가정과 상품 전략을 다시 점검해야 해요."},"pre":["방카슈랑스","25% 룰"]},{"id":"2026-10-31-2","date":"2026-10-31","tag":"보험사 실적","title":"보험 계열사가 가른 금융지주 성적표, 하나만 마이너스였던 이유","predict":{"q":"하나손해보험의 3분기 누적 순손실 846억 원 가운데, 금감원 계리가정 개편에 따른 일회성 손실은 얼마였을까요?","options":["522억 원","341억 원","505억 원"],"answer":2,"reveal":"**505억 원**이에요. 이걸 빼도 순손실은 341억 원이라, **일회성 요인만으로 설명되지 않는 적자**가 남아 있어요."},"numbers":[{"label":"KB금융 보험 계열사 기여도","value":"15.4%","note":"4대 금융지주 중 1위"},{"label":"하나금융 보험 계열사 기여도","value":"−2.46%","note":"4곳 중 유일한 마이너스"},{"label":"하나손해보험 누적 순손실","value":"846억 원","note":"작년 324억 원 손실에서 522억 원 확대"},{"label":"계리가정 개편 일회성 손실","value":"505억 원","note":"빼면 순손실 341억 원"}],"points":["4대 금융지주의 3분기 누적 순이익에서 보험 계열사가 보탠 몫은 KB 15.4%, 신한 7.78%, 우리 3.13%, 하나 −2.46%였어요. 하나생명도 작년 302억 원 흑자에서 **47억 원 적자로 돌아섰어요**.","하나손해보험 순손실은 $$505+341=846\\;(\\text{억 원})$$ 으로 나눠 볼 수 있어요. 505억 원은 계리가정 개편 영향이고, 나머지에는 **해마다 200억 원이 넘는 전산 감가상각비**와 장기·자동차보험을 키우며 늘어난 사업비가 영향을 줬어요.","다른 지주도 쉽지 않았어요. 신한라이프 순이익은 4,194억 원으로 18.5% 줄었고, 동양생명은 보험손익이 41.1% 늘었지만 투자손익이 420억 원 적자로 돌아섰어요. 우리금융 계열 ABL생명도 적자였어요."],"why":"실적 기사에서 **'일회성'이라는 말을 들으면 그걸 뺀 숫자를 꼭 따로 보세요**. 하나손해보험은 계리가정 개편 영향을 빼도 341억 원 적자라서, 회사의 기본 수익 구조를 고치는 게 과제예요. 또 계리가정 개편은 한 회사만의 일이 아니라 업계 전체에 적용된 감독 변화라서, 같은 변화가 회사마다 얼마나 다른 크기로 실적에 나타났는지 비교하면 각 회사 가정의 보수성을 짐작해볼 수 있어요.","chain":["금감원이 계리가정을 더 엄격하게 쓰도록 개편","하나손해보험에 505억 원 일회성 손실 반영","전산 감가상각비와 사업비 부담까지 겹쳐 누적 846억 원 적자","하나생명도 적자로 돌아서 하나금융 보험 기여도 −2.46%","KB는 15.4%로 보험 계열사가 지주 실적을 받쳐줌","보험 계열사의 체력이 금융지주 성적을 가르는 요인이 됨"],"role":{"q":"당신은 하나손해보험 계리팀 신입이에요. 팀장님이 묻습니다. \"일회성 505억 원을 빼면 341억 원 적자인데, 이 정도면 괜찮아진 거라고 봐도 될까?\" 어떻게 답할까요?","model":"**일회성을 빼도 적자라는 점이 더 중요한 신호**라고 답할 수 있어요. 505억 원은 계리가정 개편이 한 번 반영된 영향이라 다시 반복되지 않을 수 있지만, 남은 341억 원 손실은 해마다 200억 원이 넘는 전산 감가상각비와 장기·자동차보험을 키우며 늘어난 사업비처럼 구조적인 원인에서 나왔어요. 그래서 상품별로 보험료가 사업비와 예상 보험금을 충분히 덮는지, 새로 파는 계약이 손실계약은 아닌지를 점검해야 해요. 계리팀은 개편된 가정이 앞으로 실제 경험과 얼마나 맞는지 예실차를 꾸준히 확인하는 역할도 해야 해요."},"summary":"금융지주들 실적을 보면 보험 자회사가 얼마나 버느냐가 차이를 만들었는데, 하나금융은 보험 자회사들이 적자라서 오히려 깎아 먹었어.","interview":{"q":"하나손해보험이 흑자로 돌아서려면 무엇이 필요하다고 보나요?","guide":"결론부터: 일회성 요인을 뺀 기본 수익 구조, 특히 사업비 부담을 줄이는 것이 먼저라고 말해요.\n근거: 3분기 누적 순손실 846억 원 중 505억 원은 계리가정 개편 영향이지만, 이를 빼도 341억 원 적자이고 해마다 200억 원 넘는 전산 감가상각비가 있어요.\n관점: 상품개발·계리 관점에서 상품별 수익성을 점검하고, 새 계약이 손실계약이 되지 않게 보험료와 가정을 관리하겠다고 말해요.\n마무리: 외형을 키운 만큼 수익성을 함께 챙기는 데 기여하고 싶다고 마무리해요."},"quiz":[{"q":"하나손해보험 순손실 846억 원 중 계리가정 개편 영향을 뺀 나머지는?","o":["324억 원","341억 원","522억 원"],"a":1,"e":"846억 원에서 일회성 505억 원을 빼면 341억 원이 남아요. 일회성을 빼도 적자예요."},{"q":"4대 금융지주 가운데 보험 계열사 기여도가 가장 높은 곳은?","o":["신한금융","우리금융","KB금융"],"a":2,"e":"KB금융이 15.4%로 가장 높았고, 하나금융은 −2.46%로 유일하게 마이너스였어요."},{"q":"실적 기사에서 '일회성 손실'을 볼 때 가장 알맞은 태도는?","o":["일회성을 뺀 숫자도 따로 보고, 남은 손실의 원인을 확인한다","일회성을 뺀 숫자만 보고, 일회성 손실은 신경 쓰지 않는다","일회성 손실의 크기와 상관없이 전체 손실을 구조적 문제로 본다"],"a":0,"deep":true,"e":"일회성 요인을 빼고도 남는 손익이 회사의 기본 체력을 보여줘요. 그 원인을 따로 확인해야 해요."}],"terms":[{"t":"계리가정","d":"보험료와 보험부채를 계산할 때 쓰는 예상 손해율, 해지율, 사업비율 같은 전제예요."},{"t":"이익 기여도","d":"금융지주 전체 순이익 가운데 특정 계열사가 벌어온 몫의 비율이에요. 손실을 내면 마이너스가 돼요."},{"t":"감가상각비","d":"전산 시스템이나 건물처럼 오래 쓰는 자산에 든 돈을 쓰는 기간에 나눠 비용으로 잡는 금액이에요."},{"t":"투자손익","d":"받은 보험료를 채권, 주식 등으로 굴려서 번 이익이에요. 금리와 시장 상황에 따라 크게 흔들려요."},{"t":"보험손익","d":"보험 영업에서 남긴 이익이에요. 받은 보험료에 비해 보험금과 비용을 얼마나 잘 관리했는지 보여줘요."}],"thread":{"id":"earnings","name":"보험사 실적"},"jobs":["계리","리스크관리"],"companies":["하나손해보험","하나생명","신한라이프","동양생명","ABL생명","KB손해보험","KB라이프"],"figs":[{"type":"bars","title":"금융지주 순이익에서 보험 계열사가 보탠 몫","unit":"%","items":[{"label":"KB","value":15.4},{"label":"신한","value":7.78},{"label":"우리","value":3.13},{"label":"하나","value":-2.46,"hi":true}],"note":"3분기 누적 기준이에요. 하나금융만 보험 계열사가 손실을 냈어요.","look":"KB가 15.4%로 가장 높고 하나만 −2.46%로 마이너스예요."},{"type":"split","title":"하나손해보험 3분기 누적 순손실 나눠 보기","items":[{"label":"계리가정 개편 일회성","value":505,"text":"505억 원"},{"label":"그 밖의 손실","value":341,"text":"341억 원"}],"note":"일회성을 빼도 341억 원 적자가 남아요.","look":"순손실 846억 원 중 505억 원은 일회성, 341억 원은 그 밖의 손실이에요."}],"sources":[{"name":"뉴스웨이","url":"https://www.newsway.co.kr/news/view?ud=2026103011021890447"},{"name":"글로벌이코노믹","url":"https://www.g-enews.com/article/Finance/2026/10/202610291528279665a6e8311f64_1"}],"brief":{"what":"3분기 누적으로 4대 금융지주 가운데 하나금융만 보험 계열사 기여도가 **−2.46%**로 마이너스였어요.","why":"하나손해보험이 계리가정 개편에 따른 일회성 손실 505억 원에 전산 감가상각비와 사업비 부담까지 겹쳐 846억 원 순손실을 냈고, 하나생명도 적자로 돌아섰기 때문이에요.","so":"실적 기사에서는 일회성을 뺀 숫자도 따로 봐야 하고, 일회성을 빼도 341억 원 적자라 기본 수익 구조를 고쳐야 해요."},"pre":["계리가정","이익 기여도"]},{"id":"2026-10-31-3","date":"2026-10-31","tag":"보험사기","title":"보험을 파는 사람이 보험사기에? 설계사·손해사정사 29명 제재","predict":{"q":"보험사기에 연루돼 제재받은 보험업 종사자 29명 가운데 가장 많았던 수법은 무엇일까요?","options":["허위 입원","교통사고 조작","진료기록 조작"],"answer":1,"reveal":"**교통사고 조작이 16명**으로 가장 많았어요. 29명 가운데 28명이 보험설계사였고, **19명은 등록이 취소**됐어요."},"comic":{"title":"보험을 아는 사람이 더 위험해","panels":[{"caption":"어느 밤, 수상한 거래","bg":"night","sign":"교통사고 조작 16명","chars":[{"who":"planner","mood":"happy","pose":"phone","say":"서류는 내가 맞춰줄게요","bubble":"talk"},{"who":"fraudster","mood":"happy","fx":"sparkle"}]},{"caption":"금감원 검사 결과","bg":"office","sign":"종사자 29명 제재","chars":[{"who":"regulator","mood":"angry","pose":"doc","say":"보험을 파는 분이 사기라니요!","bubble":"shout"},{"who":"planner","mood":"surprised","fx":"exclaim"}]},{"caption":"가장 무거운 처분","bg":"focus","sign":"등록취소 19명","chars":[{"who":"planner","mood":"sad","pose":"worry","fx":"gloom","say":"이제 설계사 일을 못 해요…"}]},{"caption":"망고 계리사의 정리","bg":"office","chars":[{"who":"mango","mood":"thinking","pose":"point","fx":"idea","say":"새는 보험금은 모두의 보험료예요"},{"who":"carrot","mood":"thinking","pose":"think","say":"내 보험료에도 들어가는구나"}]}]},"numbers":[{"label":"제재받은 보험업 종사자","value":"29명","note":"보험설계사 28명, 손해사정사 1명"},{"label":"등록취소","value":"19명","note":"가장 무거운 처분"},{"label":"업무정지","value":"10명","note":"180일 7명, 90일 3명"},{"label":"교통사고 조작","value":"16명","note":"가장 많은 수법"}],"points":["금융위원회가 금감원 검사 결과를 바탕으로 보험사기에 연루된 보험업 종사자 29명을 제재했어요. **19명은 등록취소**, 7명은 업무정지 180일, 3명은 업무정지 90일을 받았어요.","수법은 교통사고 조작 16명, 허위 입원 5명, 진료기록 조작 4명, 허위·과다 진단 2명, 고지의무 위반 1명이었어요. 보험을 잘 아는 사람이 끼면 **서류가 그럴듯해져서 잡아내기가 더 어려울 수 있어요**."],"why":"보험사기로 새는 보험금은 결국 **손해율을 올리고, 다음 보험료 계산에 반영돼** 정직한 가입자 부담이 될 수 있어요. 특히 설계사나 손해사정사처럼 보험 구조를 잘 아는 내부자가 끼면 겉으로는 정상 청구처럼 보여서 손해율 통계에 섞여 들어가요. 계리·상품개발 관점에서는 사고 조작이 잦은 담보(예: 교통사고 관련 보장)가 무엇인지, 그 담보의 경험 통계가 사기로 부풀려지지 않았는지 함께 살펴보는 습관이 필요해요.","chain":["보험을 잘 아는 설계사·손해사정사가 사기에 가담","교통사고 조작, 허위 입원 등으로 보험금을 부당하게 청구","겉으로는 정상 청구처럼 보여 적발이 어려움","부당하게 나간 보험금이 손해율을 올림","보험료 산출에 반영돼 정직한 가입자 부담이 커질 수 있음","금감원 검사로 29명 제재, 19명 등록취소"],"role":{"q":"당신은 손해보험사 보험사기 대응팀에 배치된 신입이에요. 팀장님이 묻습니다. \"외부 사기범보다 설계사가 낀 사기가 왜 더 위험할까?\" 이유를 설명해보세요.","model":"설계사는 **보험 약관과 심사 기준을 잘 알기 때문에** 서류를 심사 기준에 맞춰 그럴듯하게 꾸밀 수 있어요. 그래서 겉으로는 정상 청구와 구분이 어렵고, 적발되기 전까지 같은 방식이 여러 건 반복될 수 있어요. 또 가입자와 직접 만나는 사람이라 가입자를 끌어들이기도 쉬워요. 이번에 제재받은 29명 가운데 28명이 설계사였고 교통사고 조작이 16명으로 가장 많았던 점을 보면, **특정 설계사나 특정 담보에 청구가 몰리는 패턴**을 데이터로 살피는 게 중요해요."},"summary":"보험을 파는 설계사들이 오히려 교통사고를 꾸미거나 가짜 입원을 도와서 보험금을 타내다 걸려서 29명이 자격 취소나 정지를 당했어.","interview":{"q":"보험사기가 보험사와 소비자에게 어떤 영향을 준다고 생각하나요?","guide":"결론부터: 보험사기는 손해율을 올려 결국 정직한 가입자의 보험료 부담으로 이어진다고 말해요.\n근거: 금융위원회가 보험사기에 연루된 종사자 29명을 제재했고, 19명은 등록취소됐으며 교통사고 조작이 16명으로 가장 많았어요.\n관점: 계리·상품개발 관점에서는 사기로 부풀려진 청구가 경험 통계에 섞이면 위험률이 왜곡될 수 있어 담보별 청구 패턴을 살펴야 한다고 말해요.\n마무리: 데이터로 이상 패턴을 찾는 일에 관심이 있다고 마무리해요."},"quiz":[{"q":"이번 제재에서 가장 많았던 보험사기 수법은?","o":["진료기록 조작","허위 입원","교통사고 조작"],"a":2,"e":"교통사고 조작이 16명으로 가장 많았어요."},{"q":"보험사기로 부당하게 나간 보험금이 정직한 가입자에게 영향을 주는 경로는?","o":["손해율이 올라 보험료 산출에 반영된다","사기 적발 비용이 정직한 가입자의 보험금에서 바로 차감된다","설계사 수수료가 줄어 보험료가 내려간다"],"a":0,"e":"보험금이 부풀려지면 손해율이 오르고, 그 통계가 다음 보험료 계산에 반영될 수 있어요."},{"q":"제재받은 29명 가운데 등록이 취소된 사람은 몇 명일까?","o":["10명","19명","29명"],"a":1,"e":"19명이 등록취소, 10명이 업무정지를 받았어요."}],"terms":[{"t":"보험사기","d":"사고를 꾸미거나 피해를 부풀려 보험금을 부당하게 받는 행위예요."},{"t":"등록취소","d":"설계사나 손해사정사의 등록을 없애 더 이상 그 일을 할 수 없게 하는 무거운 처분이에요."},{"t":"손해사정사","d":"사고가 났을 때 손해액을 조사하고 보험금이 얼마인지 산정하는 전문가예요."},{"t":"고지의무","d":"보험에 들 때 건강 상태 같은 중요한 사실을 보험사에 사실대로 알려야 하는 의무예요."},{"t":"손해율","d":"보험사가 받은 보험료 가운데 보험금으로 나간 돈의 비율이에요. 높을수록 보험사 수익이 나빠져요."}],"thread":{"id":"fraud","name":"보험사기 대응"},"jobs":["보상·손해사정","언더라이팅","영업·채널"],"figs":[{"type":"bars","title":"보험사기 연루 종사자, 수법별 인원","unit":"명","items":[{"label":"교통사고 조작","value":16,"hi":true},{"label":"허위 입원","value":5},{"label":"진료기록 조작","value":4},{"label":"허위·과다 진단","value":2},{"label":"고지의무 위반","value":1}],"note":"합하면 28명이에요. 나머지 1명의 수법은 기사에 나오지 않았어요.","look":"교통사고 조작이 16명으로 가장 많고 허위 입원이 5명이에요."},{"type":"split","title":"29명이 받은 처분","items":[{"label":"등록취소","value":19,"text":"19명"},{"label":"업무정지 180일","value":7,"text":"7명"},{"label":"업무정지 90일","value":3,"text":"3명"}],"look":"29명 중 19명이 등록취소, 7명이 업무정지 180일이에요."}],"sources":[{"name":"아시아경제","url":"https://view.asiae.co.kr/article/2026102914040657509"}],"brief":{"what":"금융위원회가 보험사기에 연루된 보험업 종사자 29명을 제재했고, 이 가운데 19명은 등록이 취소됐어요.","why":"설계사와 손해사정사처럼 보험을 잘 아는 사람이 끼면 서류가 그럴듯해져 적발이 더 어렵기 때문이에요.","so":"부당하게 나간 보험금은 손해율을 올려 정직한 가입자의 보험료 부담으로 이어질 수 있어, 계리·상품개발은 담보별 청구 패턴을 살펴야 해요."},"pre":["보험사기","손해율"]},{"id":"2026-10-31-4","date":"2026-10-31","tag":"자산운용","title":"생보사가 9월까지 6.2조 원을 '생산적 금융'에, 목표를 넘긴 걸까?","predict":{"q":"생명보험업계는 9월까지 생산적 금융에 6조 2,000억 원을 공급했어요. 주거용 부동산 개발 대출을 빼면 목표 3조 6,000억 원과 비교해 어땠을까요?","options":["목표보다 72% 많았다","목표와 거의 같았다","목표보다 37% 많았다"],"answer":2,"reveal":"주거용 부동산 개발 대출 1조 2,800억 원을 빼면 **4조 9,200억 원으로 목표보다 37% 많아요**. 같은 실적도 **무엇을 포함해 세느냐에 따라** 다르게 보여요."},"numbers":[{"label":"9월까지 공급액","value":"6.2조 원","note":"주거용 부동산 개발 대출 포함"},{"label":"주거용 개발 대출 제외","value":"4.92조 원","note":"목표 3.6조 원보다 37% 많음"},{"label":"5년간 투자 계획","value":"23.7조 원","note":"생명보험업계 전체"},{"label":"상생기금","value":"150억 원","note":"신용생명보험 무상 제공"}],"points":["생명보험업계가 9월까지 첨단산업, 사회기반시설 같은 생산적 금융에 6조 2,000억 원을 공급했어요. 주거용 부동산 개발 대출 1조 2,800억 원을 빼면 4조 9,200억 원이고, 이는 목표 3조 6,000억 원보다 37% 많아요. $$\\frac{4.92}{3.6}\\approx 1.37$$","업계는 앞으로 5년 동안 23조 7,000억 원을 투자하고, 150억 원 규모 상생기금으로 소상공인과 채무조정 이용자에게 **신용생명보험을 무상으로 제공**할 계획이에요."],"why":"생명보험사는 수십 년 뒤에 보험금을 줘야 하는 **긴 부채**를 갖고 있어서, 오래 묶어둘 수 있는 장기 투자처가 필요해요. 첨단산업이나 사회기반시설 투자는 이런 장기 자금과 성격이 맞을 수 있지만, 투자 위험이 크면 지급여력비율 계산에서 필요한 자본도 늘어날 수 있어요. 그래서 이런 소식을 볼 땐 **정책 목표 달성 여부뿐 아니라 수익률과 위험, 부채 만기와의 균형**을 함께 생각해보는 게 좋아요. 또 실적 숫자는 집계 기준에 따라 달라지니 무엇이 포함됐는지 꼭 확인해야 해요.","chain":["금융당국과 업계가 실물경제로 돈이 흐르는 생산적 금융을 강조","생보업계가 9월까지 6조 2,000억 원 공급","주거용 부동산 개발 대출을 빼도 목표를 37% 넘김","5년간 23조 7,000억 원 투자 계획과 상생기금 조성","보험사는 장기 부채에 맞는 장기 투자처를 늘릴 수 있음","다만 투자 위험과 필요한 자본도 함께 관리해야 함"],"role":{"q":"당신은 생명보험사 리스크관리팀 신입이에요. 팀장님이 묻습니다. \"정책 따라 첨단산업 투자를 늘리면 우리한테 좋은 점과 조심할 점은 뭘까?\" 정리해보세요.","model":"좋은 점은 **긴 보험 부채에 맞춰 오래 투자할 곳이 늘어난다**는 거예요. 만기가 긴 자산이 늘면 금리가 변해도 자산과 부채가 비슷하게 움직여 충격을 줄이는 데 도움이 될 수 있어요. 조심할 점은 투자 위험이에요. 위험이 큰 자산은 손실 가능성이 크고, 지급여력비율을 계산할 때 필요한 자본도 늘어날 수 있어요. 그래서 투자 규모를 정할 때는 기대 수익률과 손실 가능성, 그리고 **지급여력비율에 미치는 영향**을 함께 따져봐야 해요."},"summary":"생명보험회사들이 올해 9월까지 첨단산업 같은 곳에 6조 원 넘게 돈을 대줬는데, 계산 기준을 엄격하게 해도 목표보다 많이 했대.","interview":{"q":"보험사가 생산적 금융에 참여하는 것을 어떻게 보나요?","guide":"결론부터: 장기 부채를 가진 보험사에 맞는 투자처가 될 수 있지만, 위험과 자본 부담을 함께 관리해야 한다고 말해요.\n근거: 생보업계는 9월까지 6조 2,000억 원을 공급했고, 주거용 부동산 개발 대출을 빼도 목표보다 37% 많은 4조 9,200억 원이었어요. 5년간 23조 7,000억 원 투자 계획도 있어요.\n관점: 계리·리스크 관점에서 자산과 부채의 만기를 맞추고, 투자 위험이 지급여력비율에 주는 영향을 따져야 한다고 말해요.\n마무리: 공공성과 수익성의 균형을 고민하는 직원이 되겠다고 마무리해요."},"quiz":[{"q":"생보업계 생산적 금융 공급액에서 주거용 부동산 개발 대출을 빼면 얼마일까?","o":["3조 6,000억 원","4조 9,200억 원","6조 2,000억 원"],"a":1,"e":"6조 2,000억 원에서 주거용 부동산 개발 대출 1조 2,800억 원을 빼면 4조 9,200억 원이에요."},{"q":"생명보험사가 장기 투자처를 필요로 하는 가장 큰 이유는?","o":["보험 부채의 만기가 자산보다 짧아서","보험금 지급이 몇 개월 안에 끝나서","보험 부채의 만기가 길어서"],"a":2,"e":"생명보험은 수십 년 뒤 보험금을 줘야 해서, 그 만기에 맞는 긴 자산이 필요해요."},{"q":"위험이 큰 자산에 많이 투자할 때 보험사가 함께 살펴야 할 지표는?","o":["지급여력비율","13회차 유지율","불완전판매비율"],"a":0,"deep":true,"e":"위험한 자산이 늘면 필요한 자본이 커져 지급여력비율에 영향을 줄 수 있어요."}],"terms":[{"t":"생산적 금융","d":"부동산이나 단순 대출보다 첨단산업, 사회기반시설처럼 실물경제 성장에 돈이 흘러가게 하는 금융이에요."},{"t":"신용생명보험","d":"대출받은 사람이 사망하는 등 사고가 나면 남은 빚을 보험금으로 갚아주는 보험이에요."},{"t":"듀레이션","d":"돈이 들어오고 나가는 시점의 평균 만기로, 금리가 변할 때 가치가 얼마나 민감하게 움직이는지 보여줘요."},{"t":"지급여력비율","d":"보험사가 위험이 닥쳐도 보험금을 줄 수 있는 능력을 보여주는 건전성 지표예요. 지금 제도의 이름을 따 킥스 비율이라고도 불러요."}],"thread":{"id":"productive-finance","name":"생산적 금융과 보험 자산운용"},"jobs":["리스크관리","계리"],"figs":[{"type":"bars","title":"생보업계 생산적 금융, 목표와 실적","unit":"조 원","items":[{"label":"목표","value":3.6},{"label":"실적(주거용 개발 대출 제외)","value":4.92,"hi":true},{"label":"실적(전체)","value":6.2}],"note":"9월까지 기준이에요. 집계 기준에 따라 실적이 달라 보여요.","look":"주거용 개발 대출을 빼면 실적 4.92조 원이 목표 3.6조 원을 넘어요."}],"sources":[{"name":"서울신문","url":"https://www.seoul.co.kr/news/economy/finance/2026/10/30/20261030032005"}],"brief":{"what":"생명보험업계가 9월까지 생산적 금융에 6조 2,000억 원을 공급했고, 주거용 부동산 개발 대출을 빼도 목표보다 **37% 많은** 4조 9,200억 원이에요.","why":"금융당국과 업계가 실물경제로 돈이 흐르는 생산적 금융을 강조하고 있고, 생보사는 긴 부채에 맞는 장기 투자처도 필요하기 때문이에요.","so":"보험사는 장기 투자처를 늘릴 수 있지만, 투자 위험이 크면 필요한 자본이 늘어 지급여력비율에 영향을 줄 수 있어요."},"pre":["생산적 금융","지급여력비율"]},{"id":"2026-10-31-5","date":"2026-10-31","tag":"해외 진출","title":"미국 보험사를 통째로 산 DB손해보험, 이제 '얼마나 버느냐'의 시간","predict":{"q":"DB손해보험이 인수한 미국 특화보험사 포테그라에서 업계가 기대하는 내년부터의 연간 이익 기여는 얼마쯤일까요?","options":["약 1,000억 원","약 9,800억 원","약 2,000억 원"],"answer":2,"reveal":"**연 2,000억 원 안팎**이에요. 다만 포테그라와 국내 사업이 모두 잘 굴러간다는 전제가 붙어 있어서, **투입한 자본만큼 수익을 내는지**가 앞으로의 관건이에요."},"numbers":[{"label":"인수 가격","value":"16억 5천만 달러","note":"포테그라 지분 100%"},{"label":"포테그라 연간 보험료","value":"약 33억 5천만 달러","note":"작년 말 기준"},{"label":"기대 이익 기여","value":"연 2,000억 원","note":"내년부터, 업계 기대"},{"label":"DB손해보험 상반기 순이익","value":"9,796억 원","note":"별도 기준, 8.0% 증가"}],"points":["DB손해보험은 2025년 9월 계약을 맺고 2026년 5월 미국 특화보험사 포테그라 지분 100%를 16억 5천만 달러에 사들였어요. **국내 보험사의 첫 미국 보험사 인수이자 업계 최대 인수합병**이에요.","포테그라는 연간 보험료 약 33억 5천만 달러, 순이익 약 1억 6천만 달러를 내고, 미국과 영국·이탈리아 등 유럽 10개국에서 영업해요.","DB손해보험은 외형보다 **수익성과 자본 효율성**에 집중하겠다며, 2028년 별도 배당성향 35%였던 주주환원 목표를 2030년까지 더 높일 계획이라고 밝혔어요."],"why":"국내 보험 시장만으로는 성장이 더뎌서, 큰 보험사들이 해외에서 새 이익원을 찾고 있어요. 하지만 해외 보험사 인수는 **사는 순간이 아니라 그 뒤 몇 년의 수익률로 평가받아요**. 다른 나라의 규제와 위험, 환율이 실적에 섞여 들어오고, 큰돈이 묶인 만큼 자본 대비 이익이 충분해야 해요. 계리·상품개발 관점에서는 해외 자회사의 상품과 위험 구조가 국내와 얼마나 다른지, 그것이 그룹 전체 위험을 어떻게 나눠주는지도 생각해볼 거리예요.","chain":["국내 보험 시장의 성장이 더뎌짐","DB손해보험이 미국 특화보험사 포테그라를 16억 5천만 달러에 인수","2026년 5월 인수를 마치고 연결 실적에 반영 시작","업계는 내년부터 연 2,000억 원 안팎 이익 기여를 기대","투입 자본 대비 수익과 재무 건전성 유지가 관건","성과에 따라 주주환원 목표 달성 여부도 달라질 수 있음"],"role":{"q":"당신은 DB손해보험 전략팀 신입이에요. 임원이 묻습니다. \"포테그라 인수가 성공했는지 3년 뒤에 무엇으로 판단하면 될까?\" 기준을 제안해보세요.","model":"가장 중요한 기준은 **투입한 자본 대비 이익**이에요. 16억 5천만 달러를 들였으니, 기대처럼 연 2,000억 원 안팎의 이익이 꾸준히 나오는지 봐야 해요. 둘째는 건전성이에요. 큰 인수 뒤에도 지급여력비율을 안정적으로 유지하는지 확인해야 해요. 셋째는 위험 분산 효과예요. 미국과 유럽 사업이 국내와 다른 위험을 갖고 있다면 그룹 전체 실적의 변동이 줄었는지 볼 수 있어요. 마지막으로 이 성과가 **주주환원 목표 상향으로 이어지는지**도 판단 기준이 될 수 있어요."},"summary":"DB손해보험이 미국 보험회사를 2조 원 넘게 주고 통째로 샀는데, 이제는 그 돈만큼 실제로 이익을 내는지가 중요해졌어.","interview":{"q":"DB손해보험의 포테그라 인수를 어떻게 평가하나요?","guide":"결론부터: 국내 성장 한계를 넘는 의미 있는 시도지만, 평가는 앞으로의 자본 대비 수익으로 결정된다고 말해요.\n근거: 지분 100%를 16억 5천만 달러에 샀고, 포테그라는 연간 보험료 약 33억 5천만 달러, 순이익 약 1억 6천만 달러를 내요. 업계는 내년부터 연 2,000억 원 안팎 이익 기여를 기대해요.\n관점: 상품개발·계리 관점에서 해외 사업의 위험 구조와 국내 상품의 차이를 배우고, 그룹 위험 분산 효과를 볼 수 있다고 말해요.\n마무리: 해외 사업과 국내 사업이 함께 시너지를 내는 데 기여하고 싶다고 마무리해요."},"quiz":[{"q":"DB손해보험이 포테그라 지분 100%를 사들인 가격은?","o":["16억 5천만 달러","33억 5천만 달러","1억 6천만 달러"],"a":0,"e":"인수 가격은 16억 5천만 달러예요. 33억 5천만 달러는 포테그라의 연간 보험료예요."},{"q":"해외 보험사 인수의 성공을 판단할 때 가장 중요한 기준으로 알맞은 것은?","o":["인수한 회사가 거두는 연간 보험료의 규모","인수 첫해에 늘어난 연결 매출의 크기","투입한 자본 대비 꾸준히 나오는 이익"],"a":2,"e":"큰돈을 들인 만큼 그 자본 대비 이익을 꾸준히 내는지가 핵심이에요."},{"q":"배당성향이 35%라는 뜻은?","o":["자기자본의 35%를 주주에게 배당한다","순이익의 35%를 주주에게 배당한다","순이익의 35%를 사내에 쌓아 둔다"],"a":1,"deep":true,"e":"배당성향은 순이익 가운데 배당으로 나눠준 돈의 비율이에요."}],"terms":[{"t":"특화보험사","d":"일반 보험사가 잘 다루지 않는 특정 분야의 위험을 전문으로 보장하는 보험사예요."},{"t":"배당성향","d":"순이익 가운데 주주에게 배당으로 나눠준 돈의 비율이에요."},{"t":"자본 효율성","d":"회사가 쓴 자본에 비해 이익을 얼마나 많이 내는지를 말해요."},{"t":"별도 기준","d":"자회사 실적을 합치지 않고 회사 하나만의 실적을 본 기준이에요. 자회사까지 합치면 연결 기준이에요."}],"thread":{"id":"overseas","name":"보험사 해외 진출"},"jobs":["리스크관리","상품개발"],"companies":["DB손해보험"],"figs":[{"type":"timeline","title":"DB손해보험 포테그라 인수의 흐름","items":[{"when":"2025년 9월","label":"포테그라 인수 계약"},{"when":"2026년 5월","label":"지분 100% 인수 마무리"},{"when":"2026년 10월","label":"수익성·자본 효율성 강화 방향 강조","now":true},{"when":"2027년부터","label":"연 2,000억 원 안팎 이익 기여 기대"}],"look":"2025년 9월 계약에서 2026년 5월 인수 마무리까지의 흐름을 봐요."},{"type":"bars","title":"DB손해보험 상반기 실적, 작년보다 얼마나 늘었나","unit":"%","items":[{"label":"순이익","value":8},{"label":"보험손익","value":17.6,"hi":true},{"label":"투자손익","value":8.4}],"note":"별도 기준이에요. 순이익은 9,796억 원이었어요.","look":"보험손익이 17.6% 늘어 순이익 8%보다 더 늘었어요."}],"sources":[{"name":"한국아이닷컴","url":"https://www.hankooki.com/news/articleView.html?idxno=347264"}],"brief":{"what":"DB손해보험이 2026년 5월 미국 특화보험사 포테그라 지분 100%를 16억 5천만 달러에 인수해, 국내 보험사의 첫 미국 보험사 인수를 마쳤어요.","why":"국내 보험 시장만으로는 성장이 더뎌서 큰 보험사들이 해외에서 새 이익원을 찾고 있기 때문이에요.","so":"이제 **투입한 자본만큼 이익이 나는지**가 평가 기준이고, 업계는 내년부터 연 2,000억 원 안팎의 이익 기여를 기대해요."},"pre":["특화보험사","자본 효율성"]},{"id":"2026-10-31-6","date":"2026-10-31","tag":"인수합병","title":"보험사가 캐피탈과 저축은행을 산다? 한화생명이 4,400억 원으로 애큐온캐피탈을 품은 이유","predict":{"q":"한화생명이 애큐온캐피탈을 인수하면서 자회사 애큐온저축은행도 함께 들어와요. 기존 한화저축은행과 합치면 저축은행 쪽 총자산은 어느 정도가 될까요?","options":["약 5조 1,000억 원","약 6조 5,000억 원","약 9조 7,000억 원"],"answer":1,"reveal":"애큐온저축은행(총자산 5조 1,000억 원)과 기존 한화저축은행(1조 4,000억 원)을 합치면 **약 6조 5,000억 원**으로, 업계 4위권 저축은행 그룹이 돼요. 영업 지역도 인천·경기에서 서울, 부산, 울산, 경남으로 넓어져요."},"numbers":[{"label":"한화생명 투자금액","value":"4,400억 원","note":"보통주 1,751만 1,066주를 현금으로 사요. 한화생명 자기자본의 2.65%"},{"label":"인수 후 지분율","value":"50.54%","note":"사모펀드 운용사 센트로이드PE와 공동투자"},{"label":"합산 저축은행 총자산","value":"6조 5,000억 원","note":"애큐온저축은행 5조 1,000억 원 + 한화저축은행 1조 4,000억 원"},{"label":"한화투자증권 유상증자","value":"5,000억 원","note":"한화생명과 한화자산운용이 2,500억 원씩"}],"figs":[{"type":"bars","title":"한화 쪽 저축은행 총자산, 인수 전과 후","unit":"조 원","items":[{"label":"한화저축은행(기존)","value":1.4,"text":"1조 4,000억 원"},{"label":"애큐온저축은행","value":5.1,"text":"5조 1,000억 원"},{"label":"합치면","value":6.5,"text":"6조 5,000억 원","hi":true}],"note":"기사에 나온 총자산이에요. 애큐온캐피탈 자체의 총자산은 2026년 상반기 기준 4조 6,000억 원이에요.","look":"애큐온저축은행 5조 1,000억 원이 더해져 합치면 6조 5,000억 원이에요."},{"type":"timeline","title":"애큐온캐피탈이 한화생명으로 오기까지","items":[{"when":"2019년","label":"베어링PEA가 지분 90.44%를 약 7,000억 원에 인수"},{"when":"2022년","label":"EQT파트너스가 베어링PEA를 인수하며 실질 최대주주 변경"},{"when":"2026년 6월 말","label":"한화생명, 우선협상대상자로 선정"},{"when":"2026년 9월 30일","label":"이사회 의결, 4,400억 원에 지분 50.54% 확보 결정. 한화투자증권 5,000억 원 증자 참여도 함께"},{"when":"2026년 10월 1일","label":"인수 확정 보도, 여신전문금융업 진출","now":true},{"when":"앞으로","label":"금융당국의 대주주 변경 승인을 거쳐 인수 마무리"}],"look":"9월 30일 이사회 의결로 인수가 정해졌고 당국의 대주주 변경 승인이 남았어요."}],"points":["한화생명이 사모펀드 운용사 센트로이드PE와 함께 애큐온캐피탈을 인수하기로 하고, **4,400억 원에 지분 50.54%**를 확보해요. 애큐온캐피탈이 100% 가진 애큐온저축은행도 한화생명의 손자회사가 돼요.","같은 날 한화생명과 한화자산운용은 한화투자증권 유상증자에 2,500억 원씩, 모두 5,000억 원을 넣기로 했어요. 증자 뒤 한화투자증권은 자기자본 2조 원을 넘겨 종합금융투자사업자 요건을 갖춰요.","한화생명은 보험, 증권, 자산운용에 여신금융까지 묶은 **종합금융그룹**을 목표로 해요. 다만 애큐온저축은행은 올해 상반기 순이익이 13억 원으로 1년 전보다 84.9% 줄어, 인수 뒤 수익성 회복이 과제로 꼽혀요."],"why":"보험사가 번 돈을 어디에 쓰는지는 회사의 미래 전략을 보여줘요. 보험 본업은 성장이 느려지고 있어서, 대형 보험사들은 **보험 밖에서 새 이익원**을 찾고 있어요. 그런데 보험사가 자회사 지분을 사면 그만큼 자본이 묶이고, 지급여력비율(킥스) 계산에서 주식위험 요구자본이 늘 수 있어요. 그래서 이런 뉴스를 볼 때는 \"얼마를 썼고(자기자본의 2.65%), 산 회사가 돈을 잘 버는지(저축은행 상반기 순이익 13억 원)\"를 함께 따져야 해요. 계리·리스크관리 쪽에서는 계열사 투자가 **자본 여력과 주주환원(배당)**에 어떤 영향을 주는지 숫자로 설명할 수 있어야 해요.","chain":["보험 본업 성장 둔화, 새 이익원 필요","한화생명, 4,400억 원에 애큐온캐피탈 지분 50.54% 인수 결정","애큐온저축은행까지 편입, 저축은행 총자산 6조 5,000억 원 그룹","한화투자증권 5,000억 원 증자로 종합금융투자사업자 요건 확보","보험·증권·자산운용·여신을 잇는 종합금융그룹 구조","자회사 투자로 자본이 묶여 건전성·배당 여력 점검 필요","저축은행 수익성 회복과 계열사 간 연계 상품이 성패를 가름"],"role":{"q":"당신은 한화생명 리스크관리팀 신입이에요. 회의에서 선배가 묻습니다. \"캐피탈과 저축은행을 사고 증권사 증자에도 2,500억 원을 넣었어. 보험사 입장에서 이게 좋기만 한 걸까?\" 기대 효과와 함께 따져봐야 할 위험을 설명해보세요.","model":"기대 효과는 분명하다. 보험 성장이 느려지는 상황에서 **여신금융이라는 새 이익원**을 얻고, 저축은행 그룹 총자산이 6조 5,000억 원으로 커지며 영업 지역도 서울과 부산까지 넓어진다. 보험·증권·자산운용·여신을 잇는 연계 상품과 교차 판매도 가능해진다. 하지만 따져볼 점도 있다. 첫째, 인수에 쓴 4,400억 원과 증자 2,500억 원만큼 자본이 계열사에 묶여 **지급여력비율(킥스)과 배당 여력**에 부담이 될 수 있다. 둘째, 애큐온저축은행은 상반기 순이익이 13억 원으로 84.9% 줄어 수익성 회복이 필요하다. 셋째, 금융당국의 대주주 변경 승인이 남아 있다. 그래서 투자 효과를 자본 비용과 함께 숫자로 점검해야 한다."},"summary":"한화생명이 4,400억 원을 내고 캐피탈 회사랑 그 밑의 저축은행까지 사들였어. 보험만으로는 성장이 더뎌서 대출·증권까지 다 하는 종합금융그룹이 되겠다는 건데, 산 저축은행이 요즘 돈을 잘 못 벌고 자본도 묶이니까 잘 굴러갈지는 지켜봐야 해.","interview":{"q":"한화생명이 애큐온캐피탈 인수와 한화투자증권 증자로 종합금융그룹을 추진하고 있어요. 한화생명 입장에서 이 전략의 기회와 위험을 어떻게 보나요?","guide":"결론부터: 성장이 느린 보험 본업을 보완할 새 이익원이라는 기회가 있지만, 자본 부담과 자회사 수익성을 함께 관리해야 한다고 말해요.\n근거: 4,400억 원(자기자본의 2.65%)으로 지분 50.54%를 확보했고, 저축은행 총자산은 6조 5,000억 원이 돼요. 반면 애큐온저축은행 상반기 순이익은 13억 원으로 84.9% 줄었어요.\n관점: 계리·리스크관리 쪽에서는 계열사 지분 투자가 지급여력비율(킥스)의 요구자본과 배당 여력에 주는 영향을 숫자로 따져봐야 한다는 점을 짚어요.\n마무리: 보험 고객을 대출·투자 상품과 연결하는 시너지가 실제 이익으로 이어지는지가 성패를 가를 것이라고 정리해요."},"quiz":[{"q":"한화생명이 애큐온캐피탈 인수로 확보하게 되는 지분율은?","o":["50.54%","90.44%","100%"],"a":0,"e":"센트로이드PE와 공동투자해 4,400억 원에 지분 50.54%를 확보해요."},{"q":"한화생명과 한화자산운용이 한화투자증권 유상증자에 참여한 주된 목적은?","o":["애큐온캐피탈 인수 대금을 한화투자증권이 대신 내게 하려고","한화투자증권을 한화생명의 완전 자회사로 만들려고","자기자본 2조 원을 넘겨 종합금융투자사업자 요건을 갖추려고"],"a":2,"e":"두 회사가 2,500억 원씩 모두 5,000억 원을 넣으면 한화투자증권 자기자본이 2조 원을 넘어 지정 요건을 충족해요."},{"q":"보험사가 계열 금융사 지분을 많이 사들일 때 계리·리스크관리 쪽에서 가장 먼저 점검할 것으로 알맞은 것은?","o":["인수한 회사가 팔던 대출상품의 금리가 예정이율과 같은지","자회사 지분에 묶인 자본이 지급여력비율과 배당 여력에 주는 영향","인수 뒤 늘어난 자회사 직원들의 단체보험 가입 규모"],"a":1,"e":"지분 투자는 주식위험 요구자본을 늘릴 수 있어서 **지급여력비율(킥스)과 배당 여력**을 함께 따져야 해요.","deep":true}],"terms":[{"t":"여신전문금융업","d":"예금은 받지 않고 대출, 리스, 할부금융 같은 돈 빌려주는 일을 전문으로 하는 금융업이에요. 캐피탈사와 카드사가 대표적이에요."},{"t":"손자회사","d":"자회사가 지분을 가진 회사예요. 한화생명의 자회사가 될 애큐온캐피탈이 애큐온저축은행을 100% 가지고 있어서 손자회사가 돼요."},{"t":"유상증자","d":"회사가 새 주식을 발행해 돈을 받고 팔아 자본을 늘리는 방법이에요."},{"t":"종합금융투자사업자","d":"자기자본이 일정 규모를 넘는 대형 증권사에 기업 대출과 투자 업무를 더 넓게 허용하는 제도예요."},{"t":"대주주 변경 승인","d":"금융회사의 최대주주가 바뀔 때 금융당국이 새 주인의 자격을 심사해 허락하는 절차예요."}],"thread":{"id":"insurer-mna","name":"보험사 인수합병과 사업 확장"},"jobs":["리스크관리","계리"],"companies":["한화생명"],"sources":[{"name":"뉴스토마토","url":"https://newstomato.com/ReadNews.aspx?no=1315376"},{"name":"경제타임스","url":"https://www.ket.kr/news/article.html?no=41130"},{"name":"IB토마토","url":"https://www.ibtomato.com/ExternalView.aspx?type=1&no=19540"}],"brief":{"what":"한화생명이 센트로이드PE와 함께 **4,400억 원에 애큐온캐피탈 지분 50.54%**를 사기로 했어요. 같은 날 한화투자증권 유상증자에도 모두 5,000억 원을 넣기로 했어요.","why":"보험 본업 성장이 느려지면서 대형 보험사들이 보험 밖에서 새 이익원을 찾고 있고, 한화생명은 보험·증권·자산운용에 여신금융까지 묶은 종합금융그룹을 목표로 해요.","so":"저축은행 총자산이 6조 5,000억 원으로 커지지만, 자본이 계열사에 묶여 **지급여력비율(킥스)과 배당 여력**을 따져야 하고 애큐온저축은행의 수익성 회복도 과제예요."},"pre":["여신전문금융업","손자회사"]},{"id":"2026-10-31-7","date":"2026-10-31","tag":"회계제도","title":"생명보험사 부채가 1년 새 87조 원 줄었다? 계약이 사라진 게 아니라 금리가 바꾼 숫자","predict":{"q":"국내 생명보험사 22곳의 보험계약부채가 1년 새 87조 원(14.1%) 줄었어요. 가장 큰 이유는 무엇일까요?","options":["가입자들이 보험을 대거 해지해 장기 계약이 크게 줄어서","장기금리가 내려 할인율이 낮아지면서 미래에 줄 돈의 현재가치가 줄어서","장기금리가 올라 부채를 현재가치로 바꿀 때 쓰는 할인율이 높아져서"],"answer":2,"reveal":"보험계약부채는 앞으로 나갈 돈을 **할인율로 현재가치로 바꾼 값**이에요. 국고채 10년물 금리가 1년 전 2.8%대에서 4.45%로 오르자 할인율도 올라 부채가 작게 계산됐어요. 계약이 사라진 것이 아니라 **금리로 다시 잰 결과**예요."},"numbers":[{"label":"생보사 22곳 보험계약부채","value":"530조 원","note":"2026년 2분기 말 530조 4,585억 원. 1년 전 617조 5,158억 원"},{"label":"1년 새 감소","value":"−87조 원","note":"87조 573억 원, 14.10% 감소. 22곳 중 21곳이 줄었어요"},{"label":"삼성·한화·교보 감소분","value":"−50.9조 원","note":"업계 전체 감소분의 58.4%"},{"label":"국고채 10년물 금리","value":"4.45%","note":"1년 전 2.8%대에서 1.6%포인트 넘게 상승"}],"figs":[{"type":"bars","title":"대형 생보사 보험계약부채, 1년 새 얼마나 줄었나","unit":"조 원","items":[{"label":"삼성생명","value":-25.9,"text":"−25조 8,918억 원(−14.35%)","hi":true},{"label":"한화생명","value":-13,"text":"−13조 469억 원(−15.15%)"},{"label":"교보생명","value":-11.9,"text":"−11조 9,245억 원(−14.27%)"},{"label":"신한라이프","value":-7.3,"text":"−7조 2,538억 원(−16.46%)"},{"label":"NH농협생명","value":-4.7,"text":"−4조 7,396억 원(−10.07%)"},{"label":"동양생명","value":-4,"text":"−3조 9,628억 원(−14.15%)"},{"label":"흥국생명","value":-3.3,"text":"−3조 2,762억 원(−18.76%)"}],"note":"2025년 2분기 말과 2026년 2분기 말 비교, 생명보험협회 공시 기준이에요. 막대 길이는 소수 첫째 자리까지 반올림했어요.","look":"삼성생명이 −25조 8,918억 원으로 가장 크게 줄었고 일곱 곳 모두 줄었어요."},{"type":"compare","title":"금리가 오르면 보험사 장부에서 생기는 일","left":"부채 쪽","right":"자산 쪽","rows":[{"label":"무엇이 바뀌나","left":"할인율이 올라 보험계약부채의 현재가치가 줄어요","right":"오래 들고 있는 장기채의 평가가치가 떨어져요"},{"label":"이번 숫자","left":"생보사 부채 87조 원 감소","right":"기타포괄손익누계액이 2023년 말 28조 8,000억 원에서 2024년 말 3,000억 원으로 감소"},{"label":"함께 봐야 할 것","left":"어떤 계리가정으로 계산했는지","right":"부채와 같은 방향으로 움직였는지(듀레이션 갭)"}],"note":"기사에 나온 숫자만 썼어요. 기타포괄손익누계액은 업계 전체 기준이에요.","look":"금리가 오르면 부채는 줄지만 자산인 장기채 평가가치도 함께 떨어져요."}],"comic":{"title":"부채가 줄었으니 좋은 일?","panels":[{"caption":"분기 공시를 본 가입자","bg":"home","sign":"생보사 부채 −87조","chars":[{"who":"carrot","mood":"surprised","pose":"phone","fx":"exclaim","say":"보험사 빚이 87조나 줄었대!"}]},{"caption":"보험사도 반가운 표정","bg":"office","board":"down","chars":[{"who":"insurer","mood":"happy","pose":"cheer","fx":"sparkle","say":"우리 부채가 확 줄었어요!"}]},{"caption":"계리사가 금리표를 꺼내요","bg":"meeting","sign":"국고채 10년 4.45%","chars":[{"who":"mango","mood":"thinking","pose":"point","say":"금리가 올라 할인율이 커진 거예요"},{"who":"insurer","mood":"worried","pose":"shrug"}]},{"caption":"자산 쪽도 같이 봐야 해요","bg":"office","board":"down","chars":[{"who":"mango","mood":"thinking","pose":"doc","fx":"idea","say":"채권 평가손실도 같이 봐야죠"}]}]},"points":["생명보험협회 공시에 따르면 국내 생보사 22곳의 **보험계약부채**는 2026년 2분기 말 530조 4,585억 원으로, 1년 전보다 **87조 573억 원(14.10%)** 줄었어요. 22곳 중 BNP파리바카디프생명만 늘었어요.","삼성생명(−25조 8,918억 원), 한화생명(−13조 469억 원), 교보생명(−11조 9,245억 원) 세 곳에서만 50조 8,632억 원이 줄어 전체 감소분의 58.4%를 차지했어요. 감소율로는 교보라이프플래닛생명(−37.37%), DB생명(−28.63%), 하나생명(−23.41%)이 컸어요.","주된 원인은 장기금리 상승이에요. 할인율은 국고채 금리로 만든 **무위험금리기간구조에 유동성프리미엄**을 더해 정하는데, 국고채 10년물 금리가 4.45%로 오르면서 부채의 현재가치가 줄었어요."],"why":"새 회계기준에서는 보험부채를 매 분기 지금의 금리로 다시 재요. 그래서 부채가 줄었다는 숫자는 회사가 좋아졌다는 뜻이 아닐 수 있어요. 금리가 오르면 보험사가 들고 있는 장기채 값도 떨어져서, 업계의 기타포괄손익누계액은 2023년 말 28조 8,000억 원에서 2024년 말 3,000억 원으로 줄고 자본총계도 103조 3,000억 원에서 82조 1,000억 원으로 줄었어요. 결국 중요한 건 **자산과 부채가 같은 방향으로 움직였는지**예요. 당국이 듀레이션 갭을 경영실태평가 지표에 넣고, 2027년부터 계리가정 보고서를 내게 하려는 것도 같은 이유예요. 뉴스에서 부채 숫자가 크게 바뀌면 **금리 때문인지, 가정 때문인지, 계약 때문인지**를 나눠 묻는 습관을 들이세요.","chain":["장기금리 상승(국고채 10년물 4.45%)","보험부채 할인율 상승","보험계약부채 현재가치 감소(생보 −87조 원)","같은 때 장기채 평가손실로 자산도 감소","부채 숫자만으로는 건전성 판단이 어려움","당국, 듀레이션 갭 지표와 계리가정 보고서 도입 추진"],"role":{"q":"당신은 생명보험사 계리팀 신입이에요. 임원 보고 자료를 보던 팀장님이 묻습니다. \"우리 보험계약부채가 1년 새 14% 줄었네. 이걸 '부채 감축 성과'라고 써도 될까?\" 왜 조심해야 하는지 설명해보세요.","model":"그렇게 쓰면 오해를 살 수 있다. 이번 감소는 계약이 줄거나 보험금을 덜 줘서가 아니라, 국고채 10년물 금리가 2.8%대에서 4.45%로 오르며 **할인율이 올라 현재가치가 작게 계산된 결과**다. 같은 금리 상승으로 우리가 가진 장기채 평가가치도 떨어졌기 때문에 자산 쪽 변화를 함께 보여줘야 한다. 그래서 보고서에는 부채 변동을 금리 효과, 계리가정 변경 효과, 계약 변동 효과로 나눠 적고, **자산과 부채의 듀레이션 차이**가 어떻게 바뀌었는지 덧붙이는 것이 좋다. 금리가 다시 내리면 부채는 그대로 다시 커질 수 있다는 점도 짚어야 한다."},"summary":"생명보험사 빚(보험부채)이 1년 만에 87조나 줄었는데, 계약이 없어진 게 아니라 금리가 올라서 미래에 줄 돈을 지금 가치로 작게 계산했기 때문이야. 금리 오르면 보험사가 가진 채권 값도 떨어지니까 좋아졌다고 단정하면 안 돼.","interview":{"q":"생명보험사 보험계약부채가 1년 새 87조 원 줄었다는 기사를 보고 무엇을 먼저 확인하겠어요?","guide":"결론부터: 부채 감소가 금리, 계리가정, 계약 중 무엇 때문인지 먼저 나눠 보겠다고 말해요.\n근거: 22곳 부채가 617조 원에서 530조 원으로 14.1% 줄었는데, 같은 기간 국고채 10년물 금리가 2.8%대에서 4.45%로 올랐어요.\n관점: 계리 직무라면 할인율 상승이 부채를 줄이는 만큼 장기채 평가손실이 자산을 줄이므로, 자산·부채 듀레이션 차이와 자본 변화를 함께 봐야 한다고 짚어요.\n마무리: 앞으로는 부채 규모보다 어떤 가정으로 산출했는지가 더 중요해진다는 점, 그래서 계리가정 보고서 같은 감독이 강화된다는 점으로 정리해요."},"quiz":[{"q":"이번 생보사 보험계약부채 감소의 주된 원인으로 기사가 꼽은 것은?","o":["대규모 계약 해지와 신계약 감소","장기금리 상승에 따른 할인율 상승","계리가정 변경으로 미래 보험금 예상 감소"],"a":1,"e":"할인율이 오르면 미래에 나갈 돈의 **현재가치가 작아져** 부채가 줄어요."},{"q":"삼성·한화·교보 세 곳의 감소분은 업계 전체 감소분의 얼마를 차지했나요?","o":["58.4%","약 14.1%","약 75.2%"],"a":0,"e":"세 곳에서 50조 8,632억 원이 줄어 전체 87조 573억 원의 58.4%였어요."},{"q":"금리가 오를 때 부채 감소만 보고 건전성이 좋아졌다고 말하기 어려운 이유는?","o":["금리가 오르면 보험계약마진이 같은 금액만큼 자동으로 줄어서","같은 금리 상승으로 보유 장기채의 평가가치도 떨어져 자본이 줄 수 있어서","부채가 줄면 같은 금액만큼 요구자본이 자동으로 늘어나서"],"a":1,"e":"부채와 자산이 함께 움직이므로 **듀레이션 차이**에 따라 자본이 줄 수도 있어요.","deep":true}],"terms":[{"t":"보험계약부채","d":"보험사가 앞으로 가입자에게 줄 보험금과 비용을 지금 가치로 계산해 장부에 올린 빚이에요. 최선추정부채, 위험조정, 보험계약마진으로 이뤄져요."},{"t":"할인율","d":"미래에 오갈 돈을 지금 가치로 바꿀 때 쓰는 이자율이에요. 할인율이 오르면 같은 미래 금액의 현재가치가 작아져요."},{"t":"유동성프리미엄","d":"보험부채처럼 중간에 쉽게 팔 수 없는 성격을 반영해 무위험금리에 더해 주는 추가 금리예요."},{"t":"듀레이션","d":"돈이 들어오고 나가는 시점의 평균 만기로, 금리가 변할 때 가치가 얼마나 민감하게 움직이는지 보여줘요."},{"t":"기타포괄손익","d":"채권 평가손익처럼 당기순이익에는 넣지 않고 자본에 바로 반영하는 손익이에요."}],"thread":{"id":"ifrs17","name":"새 회계기준과 보험부채"},"jobs":["계리","리스크관리"],"companies":["삼성생명","한화생명","교보생명","신한라이프","NH농협생명","동양생명","흥국생명","DB생명","하나생명"],"sources":[{"name":"CEO스코어데일리","url":"https://ceoscoredaily.com/page/view/2026093013160454719"}],"brief":{"what":"국내 생보사 22곳의 보험계약부채가 1년 새 **87조 원(14.10%) 줄어** 530조 4,585억 원이 됐어요.","why":"계약이 사라진 것이 아니라, 국고채 10년물 금리가 4.45%로 오르며 할인율이 올라 앞으로 줄 돈의 현재가치가 작게 계산된 결과예요.","so":"부채가 줄었다고 성과로 읽으면 안 돼요. 같은 금리 상승으로 장기채 평가가치도 떨어지니 **자산과 부채가 같은 방향으로 움직였는지**와 계리가정을 함께 봐야 해요."},"pre":["보험계약부채","할인율"]},{"id":"2026-10-31-8","date":"2026-10-31","tag":"건전성·자본","title":"전체 비율은 160%인데 기본자본은 마이너스? 내년 1월 시작하는 기본자본 킥스 50% 규제, 5곳이 미달","predict":{"q":"롯데손해보험의 전체 지급여력비율은 권고치 130%를 넘는데, 기본자본 지급여력비율은 마이너스예요. 이런 일이 가능한 이유는?","options":["손실을 막는 힘이 약한 보완자본에 기대어 전체 비율을 채우고 있어서","기본자본 계산에서는 이익잉여금이 빠지고 자본금만 들어가서","전체 비율은 요구자본을 작게, 기본자본 비율은 크게 잡아서"],"answer":0,"reveal":"전체 비율은 후순위채 같은 **보완자본까지 더해** 계산하지만, 기본자본 비율은 손실흡수력이 큰 자본만 봐요. 기본자본이 보완자본에 잠식되면 **기본자본 비율이 마이너스**가 될 수 있어요. 그래서 내년부터는 자본의 '양'뿐 아니라 '질'도 따져요."},"numbers":[{"label":"새 규제 기준","value":"50% 이상","note":"2027년 1월부터 기본자본 지급여력비율 유지 의무. 2035년 말까지 경과조치"},{"label":"롯데손해보험 기본자본 비율","value":"−5.3%","note":"2026년 6월 말. 3월 말 −21.4%에서 개선"},{"label":"기준 미달 회사","value":"5곳","note":"2026년 6월 말 기준"},{"label":"하나생명 기본자본 비율","value":"14.3%","note":"미달 5곳 중 플러스 비율로는 가장 낮아요"}],"figs":[{"type":"bars","title":"기본자본 지급여력비율 50% 미달 보험사(2026년 6월 말)","unit":"%","items":[{"label":"iM라이프","value":33.3,"text":"33.3%"},{"label":"KDB생명","value":33.2,"text":"33.2%"},{"label":"하나손해보험","value":22.4,"text":"22.4%"},{"label":"하나생명","value":14.3,"text":"14.3%"},{"label":"롯데손해보험","value":-5.3,"text":"−5.3%","hi":true}],"ref":{"value":50,"label":"규제 기준 50%"},"note":"CEO스코어데일리 보도 기준이에요.","look":"5곳 모두 기준 50%에 못 미치고, 롯데손해보험만 −5.3%로 마이너스예요."},{"type":"timeline","title":"롯데손해보험 기본자본 지급여력비율의 흐름","items":[{"when":"2025년 3월 말","label":"−9.5%"},{"when":"2025년 6월 말","label":"−12.9%"},{"when":"2025년 9월 말","label":"−16.8%"},{"when":"2025년 12월 말","label":"−19%"},{"when":"2026년 3월 말","label":"−21.4%로 가장 낮아짐"},{"when":"2026년 6월 말","label":"−5.3%로 개선","now":true},{"when":"2027년 1월","label":"기본자본 비율 50% 규제 시행(2035년 말까지 경과조치)"}],"look":"롯데손해보험은 −21.4%까지 내려갔다가 6월 말 −5.3%로 올랐어요."}],"comic":{"title":"자본도 질이 있다","panels":[{"caption":"건전성 공시를 본 보험사","bg":"office","sign":"전체 비율 161.9%","chars":[{"who":"insurer","mood":"happy","pose":"cheer","say":"권고치 130%는 넘었어요!"}]},{"caption":"그런데 다른 칸을 보니","bg":"focus","sign":"기본자본 비율 −5.3%","chars":[{"who":"insurer","mood":"surprised","pose":"worry","fx":"sweat","say":"마이너스라고요?"}]},{"caption":"당국이 새 기준을 알려요","bg":"meeting","sign":"내년부터 50% 이상","chars":[{"who":"regulator","mood":"thinking","pose":"point","say":"빌린 자본 말고 진짜 자본을 보세요"},{"who":"insurer","mood":"worried","pose":"shrug"}]},{"caption":"계리사의 정리","bg":"office","board":"up","chars":[{"who":"mango","mood":"thinking","pose":"doc","fx":"idea","say":"이익을 쌓아야 기본자본이 커져요"}]}]},"points":["금융당국은 2027년 1월부터 보험사가 **기본자본 지급여력비율을 50% 이상** 유지하도록 하는 규제를 시작해요. 손실흡수력이 큰 자본만으로 계산하는 비율이라, 전체 비율만 높여서는 안 되고 자본의 질을 높여야 해요. 다만 2035년 말까지 경과조치가 있어요.","2026년 6월 말 기준 50%에 못 미친 곳은 롯데손해보험(−5.3%), iM라이프(33.3%), KDB생명(33.2%), 하나손해보험(22.4%), 하나생명(14.3%) 5곳이에요.","롯데손해보험은 비율이 2026년 3월 말 −21.4%까지 떨어졌다가 6월 말 −5.3%로 좋아졌어요. 최대주주 JKL파트너스는 신한금융과의 수의계약 협상이 결렬된 뒤 **공개매각**을 준비하고 있어, 인수자는 인수대금 외에 유상증자 부담도 따져야 해요."],"why":"지급여력비율(킥스)은 가용자본을 요구자본으로 나눈 값인데, 가용자본에는 손실을 바로 막는 기본자본과 후순위채 같은 보완자본이 섞여 있어요. 전체 비율만 보면 **빚을 내서 자본을 채운 회사**도 건전해 보일 수 있어서, 당국은 기본자본 비율을 따로 규제하기로 했어요. 기본자본은 결국 이익을 쌓아야 커지니, 계리·상품개발 쪽에서는 **보험계약마진이 크고 손실계약이 적은 상품**을 만드는 것이 자본의 질과 직접 연결돼요. 인수합병 뉴스에서도 매각 가격만이 아니라 인수 뒤 넣어야 할 자본까지 함께 봐야 해요.","chain":["후순위채 등 보완자본으로 전체 비율을 채운 회사 증가","전체 비율은 높아도 손실흡수력은 약함","당국, 2027년부터 기본자본 비율 50% 규제","롯데손해보험 등 5곳 기준 미달(2026년 6월 말)","이익 축적이나 유상증자로 기본자본 확충 필요","매각 협상에서 인수자의 자본 확충 부담으로 작용"],"role":{"q":"당신은 손해보험사 리스크관리팀 신입이에요. 회의에서 팀장님이 묻습니다. \"우리 전체 지급여력비율은 160%가 넘는데, 왜 기본자본 비율 50%를 걱정해야 하지?\" 두 비율의 차이와 대응 방향을 설명해보세요.","model":"전체 비율은 기본자본에 후순위채 같은 **보완자본까지 더해** 계산하지만, 기본자본 비율은 손실흡수력이 큰 자본만 쓴다. 그래서 전체 비율이 권고치 130%를 넘어도 기본자본이 보완자본에 잠식되면 롯데손해보험(6월 말 −5.3%)처럼 마이너스가 될 수 있다. 2027년 1월부터 50% 이상을 유지해야 하므로, 단기적으로는 경과조치 기간(2035년 말까지) 안의 확충 계획을 세우고, 길게는 **이익잉여금을 쌓는 구조**를 만들어야 한다. 보험계약마진이 큰 보장성 상품을 늘리고 손실계약을 줄이는 상품 전략, 배당과 증자 계획을 함께 검토하는 것이 대응 방향이다."},"summary":"보험사 건전성 점수는 진짜 자기 돈(기본자본)이랑 빌린 돈 성격의 자본(보완자본)을 합쳐서 매기는데, 내년부터는 진짜 자기 돈만으로도 50%를 넘겨야 해. 롯데손보는 이게 마이너스라서 회사를 사려는 쪽도 돈을 더 넣어야 하는 상황이야.","interview":{"q":"기본자본 지급여력비율 규제가 도입되는 이유와, 보험사가 이를 맞추기 위해 상품 측면에서 할 수 있는 일은 무엇이라고 보나요?","guide":"결론부터: 빚 성격의 자본으로 비율만 채우는 것을 막고 자본의 질을 높이려는 규제이며, 상품 측면에서는 이익을 꾸준히 쌓는 상품 구조가 답이라고 말해요.\n근거: 2027년 1월부터 50% 이상 유지가 의무이고, 2026년 6월 말 기준 롯데손해보험(−5.3%), 하나생명(14.3%) 등 5곳이 미달이에요.\n관점: 상품개발·계리 관점에서 보험계약마진이 큰 보장성 상품을 늘리고 손실계약을 줄이면 이익잉여금이 쌓여 기본자본이 커진다는 연결을 짚어요.\n마무리: 2035년 말까지 경과조치가 있으니 단기 증자보다 수익성 있는 성장 계획이 중요하다고 정리해요."},"quiz":[{"q":"2027년 1월부터 보험사가 유지해야 하는 기본자본 지급여력비율 기준은?","o":["50% 이상","100% 이상","130% 이상"],"a":0,"e":"기본자본 비율은 **50% 이상**을 유지해야 하고, 2035년 말까지 경과조치가 있어요. 130%는 전체 비율의 권고치예요."},{"q":"전체 지급여력비율이 130%를 넘는데도 기본자본 비율이 마이너스가 될 수 있는 이유는?","o":["후순위채 같은 보완자본이 기본자본 계산에서만 두 번 차감돼서","이익잉여금이 쌓일수록 기본자본 비율이 오히려 낮아지는 구조라서","보완자본이 많아 전체 비율을 받쳐주지만 기본자본은 잠식돼 있어서"],"a":2,"e":"전체 비율은 보완자본까지 더해 계산하지만 기본자본 비율은 **손실흡수력이 큰 자본만** 봐요."},{"q":"기본자본을 늘리는 방법으로 가장 알맞지 않은 것은?","o":["이익을 쌓아 이익잉여금 늘리기","유상증자로 자본금 늘리기","후순위채를 더 발행하기"],"a":2,"e":"후순위채는 **보완자본**이라 기본자본 비율을 높이지 못해요.","deep":true}],"terms":[{"t":"기본자본","d":"손실을 막는 힘이 가장 강한 자본이에요. 자본금과 이익잉여금 등이 들어가요."},{"t":"보완자본","d":"손실을 막는 데 일부 제한이 있는 자본이에요. 후순위채 같은 자본증권이 대표적이에요."},{"t":"기본자본 지급여력비율","d":"보완자본을 빼고 기본자본만으로 계산한 지급여력비율이에요. 자본의 질을 보여줘요."},{"t":"경과조치","d":"새 규제를 바로 다 적용하지 않고 정해진 기간 동안 단계적으로 맞추도록 시간을 주는 장치예요."},{"t":"공개매각","d":"정해진 상대와만 협상하는 수의계약과 달리, 매각 공고를 내고 여러 인수 후보의 제안을 받아 파는 방식이에요."}],"thread":{"id":"kics","name":"지급여력제도(킥스)"},"jobs":["리스크관리","계리"],"companies":["롯데손해보험","하나손해보험","하나생명"],"sources":[{"name":"CEO스코어데일리","url":"https://m.ceoscoredaily.com/page/view/2026100216063938970"}],"brief":{"what":"금융당국이 2027년 1월부터 보험사가 **기본자본 지급여력비율 50% 이상**을 유지하게 하는데, 2026년 6월 말 기준 롯데손해보험을 포함한 5곳이 기준에 못 미쳐요.","why":"후순위채 같은 보완자본으로 전체 비율을 채우면 손실을 막는 힘이 약해도 건전해 보일 수 있어서, 당국이 자본의 질을 따로 보기로 했어요.","so":"보험사는 이익을 쌓아 기본자본을 키워야 하고, 계리·상품개발은 **보험계약마진이 크고 손실계약이 적은 상품**을 만드는 것이 중요해져요."},"pre":["기본자본 지급여력비율","보완자본"]},{"id":"2026-10-31-9","date":"2026-10-31","tag":"상품개발","title":"보험 '특허' 신청이 줄었다, 생보는 2배 늘고 손보는 반토막 난 이유","predict":{"q":"올해 1~9월 보험상품 배타적사용권 신청은 41건에서 36건으로 줄었어요. 생명보험사와 손해보험사 신청은 각각 어떻게 됐을까요?","options":["생보는 절반 넘게 줄고, 손보는 2배 넘게 늘었다","생보는 2배 넘게 늘고, 손보는 절반 넘게 줄었다","생보는 조금 늘고, 손보는 조금 줄었다"],"answer":1,"reveal":"생보사 신청은 10건에서 21건으로 **110% 늘었고**, 손보사는 31건에서 15건으로 **51.61% 줄었어요**. 손보사가 주로 쓰던 '보장 한도와 범위 넓히기' 방식이 보장한도 심의 강화로 막힌 영향이라는 분석이에요."},"numbers":[{"label":"전체 신청 건수","value":"36건","note":"2026년 1~9월. 1년 전 41건에서 12.20% 감소"},{"label":"생명보험사 신청","value":"21건","note":"10건에서 110.0% 증가"},{"label":"손해보험사 신청","value":"15건","note":"31건에서 51.61% 감소"},{"label":"한화손해보험 신청","value":"9건","note":"업계 최다. 이 중 6건 부여"}],"figs":[{"type":"bars","title":"배타적사용권 신청 건수, 1년 새 바뀐 회사들(1~9월)","unit":"건","items":[{"label":"한화손해보험","value":5,"text":"4건 → 9건","hi":true},{"label":"삼성생명","value":5,"text":"0건 → 5건"},{"label":"교보생명","value":5,"text":"0건 → 5건"},{"label":"흥국생명","value":2,"text":"1건 → 3건"},{"label":"한화생명","value":-4,"text":"6건 → 2건"},{"label":"흥국화재","value":-4,"text":"5건 → 1건"},{"label":"KB손해보험","value":-4,"text":"4건 → 0건"},{"label":"DB손해보험","value":-9,"text":"11건 → 2건","hi":true}],"note":"막대는 2025년 1~9월 대비 2026년 1~9월 신청 건수 변화예요.","look":"한화손해보험은 4건에서 9건으로 늘고, DB손해보험은 11건에서 2건으로 줄었어요."},{"type":"compare","title":"생명보험사와 손해보험사의 엇갈린 흐름(1~9월)","left":"생명보험사","right":"손해보험사","rows":[{"label":"신청 건수","left":"10건 → 21건","right":"31건 → 15건"},{"label":"부여 건수","left":"9건 → 20건","right":"27건 → 11건"},{"label":"수용률","left":"90.00% → 95.24%","right":"87.10% → 73.33%"}],"note":"전체 수용률은 87.80%에서 86.11%로 낮아졌어요.","look":"생보사는 신청이 10건에서 21건으로 늘고, 손보사는 31건에서 15건으로 줄었어요."}],"points":["올해 1~9월 보험상품 **배타적사용권** 신청은 36건으로 1년 전보다 12.20% 줄었고, 부여도 36건에서 31건으로 줄었어요.","손보사는 신청이 31건에서 15건으로 반토막 났어요. 지난해 15건을 모두 받아 1위였던 DB손해보험은 11건에서 2건으로 줄었고, 삼성화재와 KB손해보험은 0건이었어요. 반대로 **한화손해보험은 9건**으로 업계 최다였어요.","생보사는 10건에서 21건으로 늘었어요. 삼성생명은 5건 모두, 교보생명은 5건 중 4건을 받았어요. 손보사들이 주로 쓰던 **보장 한도·범위 넓히기 방식**이 보장한도 심의 강화로 좁아진 영향이라는 분석이 나와요."],"why":"배타적사용권은 새로운 보험상품을 만든 회사에 일정 기간 독점 판매권을 주는 제도예요. 2024년 9월 보호기간을 최대 18개월로 늘렸지만, 같은 때 남의 상품을 베끼는 경쟁을 막으려고 상품위원회 역할과 **보장한도 가이드라인**도 강화했어요. 그 결과 '한도만 키운 상품'으로는 독창성을 인정받기 어려워졌어요. 상품개발 직무라면 이 흐름에서 **한도 경쟁이 아니라 새로운 위험을 찾아 보장하는 설계**가 점점 중요해진다는 점을 읽어야 해요. 뉴스에서 '업계 최초'나 '배타적사용권 획득'이라는 말을 보면, 무엇이 새로운지와 그 위험률을 어떻게 잡았을지 함께 생각해보세요.","chain":["손보사, 보장 한도·범위 넓히기로 배타적사용권 경쟁","당국, 베끼기 경쟁 막으려 보장한도 심의 강화","한도 확대형 상품은 독창성 인정이 어려워짐","손보사 신청 31건 → 15건, 수용률 73.33%로 하락","생보사는 새 구조 상품으로 신청 21건으로 증가","새로운 위험을 보장하는 설계 역량이 차별화 요소"],"role":{"q":"당신은 손해보험사 상품개발팀 신입이에요. 팀장님이 묻습니다. \"작년엔 담보 한도를 키워서 배타적사용권을 꽤 받았는데 올해는 왜 이렇게 어렵지? 다음 신청은 어떤 방향으로 준비해야 할까?\" 이유와 방향을 설명해보세요.","model":"당국이 2024년 9월 보호기간을 늘리면서 동시에 상품위원회 역할과 **보장한도 가이드라인**을 강화했기 때문이다. 담보 한도나 범위를 넓히는 방식은 독창성으로 인정받기 어려워졌고, 실제로 손보업계 수용률은 87.10%에서 73.33%로 떨어졌다. 다음 신청은 **기존에 보장하지 않던 위험**을 새로 정의하거나 보장 구조 자체를 바꾸는 방향으로 준비해야 한다. 이때 새 위험은 경험 통계가 부족하므로 위험률을 어떻게 근거 있게 잡을지, 역선택을 어떻게 막을지를 함께 설계해 심사에서 설명할 수 있어야 한다."},"summary":"보험 상품도 특허처럼 몇 달 동안 혼자 팔 수 있는 권리(배타적사용권)가 있는데, 손보사들이 보장 한도만 키운 상품으로 따내던 길이 막혀서 신청이 반으로 줄었어. 대신 생보사들은 새로운 구조의 상품으로 두 배 넘게 신청했어.","interview":{"q":"최근 손해보험사의 배타적사용권 신청이 크게 줄었어요. 상품개발 담당자라면 이 변화를 어떻게 해석하나요?","guide":"결론부터: 한도 경쟁형 상품이 막히면서 진짜 새로운 위험을 보장하는 설계 역량이 중요해졌다고 봐요.\n근거: 손보사 신청이 31건에서 15건으로 51.61% 줄고 수용률이 73.33%로 낮아진 반면, 생보사는 10건에서 21건으로 늘었어요. 한화손해보험은 9건으로 최다였어요.\n관점: 상품개발 관점에서 새 위험은 통계가 부족하니 위험률 근거와 역선택 방지 장치를 함께 설계해야 심사를 통과할 수 있다고 짚어요.\n마무리: 배타적사용권 건수보다 그 상품이 실제로 팔리고 손해율이 안정적인지가 진짜 성과라고 정리해요."},"quiz":[{"q":"2026년 1~9월 배타적사용권을 가장 많이 신청한 회사는?","o":["DB손해보험","삼성생명","한화손해보험"],"a":2,"e":"한화손해보험이 9건으로 생·손보 통틀어 최다였고, 6건을 부여받았어요."},{"q":"손보사 신청이 줄어든 배경으로 기사가 든 것은?","o":["배타적사용권 보호기간이 짧아져 독점 효과가 줄어서","보장한도 심의가 강화돼 한도·범위 확대 방식이 어려워져서","손보사의 신상품 개발 인력이 크게 줄어서"],"a":1,"e":"2024년 9월 보호기간은 오히려 늘었지만, **보장한도 가이드라인**과 상품위원회 역할도 강화됐어요."},{"q":"새로운 위험을 보장하는 상품을 만들 때 상품개발 쪽에서 특히 신경 써야 할 것은?","o":["보장 한도를 경쟁사보다 크게 키우는 것","보험료를 경쟁사보다 최대한 낮추는 것","경험 통계가 부족한 위험률의 근거와 역선택 방지 장치"],"a":2,"e":"새 위험은 쌓인 통계가 적어 **위험률을 보수적으로, 근거 있게** 잡아야 해요.","deep":true}],"terms":[{"t":"배타적사용권","d":"독창적인 보험상품을 만든 회사에 일정 기간 다른 회사가 비슷한 상품을 팔지 못하게 하는 독점 판매 권리예요. 보험업계의 특허처럼 쓰여요."},{"t":"수용률","d":"신청한 건 가운데 실제로 인정받은 건의 비율이에요."},{"t":"상품위원회","d":"생명·손해보험협회에 있는 심의 기구로, 배타적사용권 신청 상품의 독창성 등을 심사해요."},{"t":"역선택","d":"위험이 높은 사람일수록 보험에 더 가입하려는 현상이에요. 보험사가 위험을 정확히 알기 어려울 때 생겨요."}],"thread":{"id":"product-competition","name":"보험상품 개발 경쟁"},"jobs":["상품개발","계리"],"companies":["한화손해보험","DB손해보험","삼성생명","교보생명","한화생명","흥국생명","흥국화재","KB손해보험","삼성화재"],"sources":[{"name":"CEO스코어데일리","url":"https://ceoscoredaily.com/page/view/2026093013260616852"}],"brief":{"what":"올해 1~9월 배타적사용권 신청은 36건으로 1년 전보다 12.20% 줄었는데, 생보사는 10건에서 21건으로 늘고 손보사는 31건에서 15건으로 반토막 났어요.","why":"손보사들이 주로 쓰던 보장 한도와 범위 넓히기 방식이 보장한도 가이드라인과 상품위원회 역할 강화로 독창성을 인정받기 어려워졌다는 분석이 나와요.","so":"상품개발은 **한도 경쟁이 아니라 새로운 위험을 찾아 보장하는 설계**가 중요해졌어요. 손보사의 수용률은 87.10%에서 73.33%로 낮아졌어요."},"pre":["배타적사용권","수용률"]},{"id":"2026-10-31-10","date":"2026-10-31","tag":"판매채널","title":"계약이 두 달 만에 깨지면 수수료를 120% 토해내라? 국감에 처음 선 대형 보험대리점 대표","predict":{"q":"보험사는 계약이 초기에 해지되면 법인보험대리점에 준 수수료의 95~100%를 돌려받아요. 그런데 국감에서 문제가 된 한 대형 보험대리점은 소속 설계사에게 최대 얼마를 돌려받는 조항을 두고 있었을까요?","options":["최대 120%","최대 110%","보험사와 같은 95~100%"],"answer":0,"reveal":"설계사 위촉계약에 **최대 120% 환수** 조항이 있었어요. 보험대리점이 보험사에 돌려주는 것보다 설계사에게 **20~25%포인트 더** 받는 구조라서, 그 차액이 어디로 가는지가 국감에서 따져졌어요."},"comic":{"title":"두 달 만에 깨진 계약, 빚은 누구에게?","panels":[{"caption":"계약을 따낸 설계사, 수수료를 먼저 받았어요","bg":"office","board":"up","chars":[{"who":"planner","mood":"happy","pose":"cheer","fx":"sparkle","say":"이번 달 수수료 들어왔다!"}]},{"caption":"그런데 두 달 만에 계약이 해지됐어요","bg":"focus","sign":"환수 120%","chars":[{"who":"planner","mood":"surprised","pose":"phone","fx":"exclaim","say":"받은 것보다 더 내라고요?","bubble":"shout"}]},{"caption":"국정감사에서 이 구조가 도마에 올랐어요","bg":"meeting","chars":[{"who":"regulator","mood":"angry","pose":"point","say":"보험사엔 100%인데 차액은 어디로?"},{"who":"planner","mood":"sad","pose":"worry","fx":"gloom"}]},{"caption":"계리사의 눈으로 다시 보면","bg":"office","board":"down","chars":[{"who":"mango","mood":"thinking","pose":"doc","fx":"idea","say":"초기 해지가 많으면 해지율 가정도 흔들려요"}]}]},"figs":[{"type":"compare","title":"계약 초기 해지 때 수수료 환수, 누가 얼마를?","left":"보험사 → 보험대리점","right":"보험대리점 → 소속 설계사","rows":[{"label":"환수율","left":"95~100%","right":"최대 120%"},{"label":"차액","left":"-","right":"최대 20~25%포인트"},{"label":"설계사가 못 갚으면","left":"-","right":"지급보증보험금 수령 후 설계사 채무로 남아 추심"}],"note":"2026년 10월 8일 정무위원회 금융위원회 국정감사에서 나온 내용이에요.","look":"보험사는 대리점에 95~100%, 대리점은 설계사에게 최대 120%를 환수해요."},{"type":"bars","title":"보험대리점 설계사 지급보증보험, 건당 평균 지급액","unit":"만 원","items":[{"label":"2024년","value":543},{"label":"2025년","value":665},{"label":"2026년","value":724,"hi":true}],"note":"최근 3년간 지급된 보험금은 모두 1,290억 원이에요(국회의원실 자료).","look":"건당 평균 지급액이 2024년 543만 원에서 2026년 724만 원으로 늘었어요."}],"numbers":[{"label":"설계사 환수 조항","value":"최대 120%","note":"보험사가 보험대리점에 적용하는 비율은 95~100%"},{"label":"지급보증보험금","value":"1,290억 원","note":"최근 3년간 보험대리점 설계사 대상으로 지급"},{"label":"건당 평균 지급액","value":"724만 원","note":"2024년 543만 원에서 해마다 늘어"},{"label":"지난 6월 과태료","value":"53억 1,110만 원","note":"부당승환 등으로 기관경고와 함께 부과"}],"points":["10월 8일 금융위원회 국정감사에서 **대형 법인보험대리점 대표가 처음으로 일반 증인**으로 나왔어요. 소속 설계사 위촉계약에 계약이 초기에 해지되면 받은 수수료의 최대 120%를 돌려받는 조항이 있었기 때문이에요.","보험사가 보험대리점에 적용하는 환수율은 95~100%라서, 설계사에게 더 걷은 차액의 행방과 산정 근거가 문제가 됐어요. 대표는 2~3차월 해지에 대한 **'징벌적으로 만든 조항'**이라고 인정하면서, 오래 유지되면 보험사보다 조건이 느슨해진다고 해명했어요.","설계사가 환수금을 못 갚으면 회사는 지급보증보험으로 돈을 받고 설계사에게는 빚이 남아요. 최근 3년간 이런 보험금이 1,290억 원이었고, 금융위원장은 환수·공제 실태와 보험대리점 본사 책임을 살펴보겠다고 답했어요."],"why":"보험 영업은 수수료를 계약 초기에 몰아서 주는 구조라서, 계약이 금방 깨지면 **수수료 환수**가 생겨요. 이번 국감은 그 부담이 판매 조직 안에서 맨 끝의 설계사에게 더 크게 넘어갈 수 있다는 점을 보여줬어요. 이런 구조는 설계사가 환수를 피하려고 무리하게 새 계약을 만들거나 기존 계약을 갈아태우는 **부당승환**으로 이어질 수 있다는 지적이 있어요. 계리·상품개발 쪽에서는 초기 해지가 많은 채널의 계약이 해지율 가정과 보험계약마진을 흔든다는 점이 중요해요. 2027년 수수료 분급제 시행을 앞두고 '수수료를 언제, 얼마나 주고, 깨지면 얼마나 돌려받나'가 판매 품질을 좌우하는 핵심 질문이 되고 있어요.","chain":["수수료를 계약 초기에 몰아서 지급","계약 2~3개월 만에 해지","보험대리점이 설계사에게 최대 120% 환수","못 갚은 돈은 보증보험을 거쳐 설계사 빚으로","환수 피하려 무리한 신계약·갈아타기 유인","초기 해지 늘면 해지율 가정과 보험계약마진 흔들림"],"role":{"q":"당신은 생명보험사 계리팀 신입이에요. 팀장님이 국감 기사를 보여주며 묻습니다. \"보험대리점이 설계사한테 수수료를 얼마나 환수하든 그건 보험대리점 내부 문제 아니야? 우리 회사 숫자랑 무슨 상관이지?\" 계리 관점에서 상관이 있는 이유를 설명해보세요.","model":"환수 구조는 판매 행동을 바꾸고, 판매 행동은 우리 계약의 질을 바꾸기 때문에 상관이 있다. 설계사가 받은 것보다 많이 돌려줘야 하는 구조라면 환수를 피하려고 **무리한 신계약이나 갈아타기**를 만들 유인이 커지고, 이런 계약은 초기에 다시 깨질 가능성이 높다. 그러면 우리가 가정한 해지율과 실제 해지율이 어긋나 예실차가 생기고, 신계약에서 잡은 **보험계약마진**도 기대보다 빨리 사라질 수 있다. 그래서 채널별 초기 해지율과 유지율을 따로 보고, 이상한 채널은 가정과 수수료 정책에 반영해야 한다."},"summary":"보험 계약이 두 달 만에 깨지면 설계사가 받은 수수료를 돌려줘야 하는데, 한 대형 대리점은 보험사가 받아가는 것보다 많은 최대 120%를 설계사한테 받아가서 국감에서 혼났어. 못 갚으면 설계사 빚으로 남는 구조라 당국이 살펴보겠대.","interview":{"q":"최근 국정감사에서 보험대리점의 수수료 환수 구조가 문제가 됐어요. 보험사 입장에서 이 문제를 왜 신경 써야 할까요?","guide":"결론부터: 환수 구조가 판매 품질과 계약 유지율을 좌우해 결국 보험사의 수익성과 소비자 신뢰로 돌아오기 때문이에요.\n근거: 보험사는 보험대리점에 95~100%를 환수하는데 한 대형 보험대리점은 설계사에게 최대 120%를 환수했고, 최근 3년 보험대리점 설계사 지급보증보험금이 1,290억 원이었어요.\n관점: 계리 관점에서 초기 해지가 많은 채널은 해지율 가정과 보험계약마진을 흔드니, 채널별 유지율을 따로 관리해야 해요.\n마무리: 2027년 분급제 시행에 맞춰 판매 품질에 따라 수수료를 주는 구조를 함께 설계하는 것이 보험사 몫이라고 정리해요."},"quiz":[{"q":"국감에서 문제가 된 대형 보험대리점의 설계사 수수료 환수 조항은 최대 몇 %였나요?","o":["110%","120%","100%"],"a":1,"e":"보험사가 보험대리점에 적용하는 95~100%보다 높은 **최대 120%**였어요."},{"q":"설계사가 환수금을 갚지 못하면 어떻게 된다고 지적됐나요?","o":["지급보증보험으로 회사가 돈을 받으면 설계사의 채무는 사라진다","보험사가 환수금을 대신 부담하고 설계사에게는 청구하지 않는다","지급보증보험으로 회사가 돈을 받고 설계사에게는 채무가 남는다"],"a":2,"e":"회사가 보증보험금을 받아도 설계사의 원래 채무는 남아 **추심으로 이어질 수 있어요**."},{"q":"계약 초기 해지가 많은 판매채널이 보험사 계리에 주는 영향으로 가장 알맞은 것은?","o":["해지율 가정과 실제가 어긋나 보험계약마진이 기대보다 빨리 줄 수 있다","해지율 가정은 맞아떨어지고 보험계약마진은 오히려 늘어난다","해지가 늘수록 보험료 수입이 늘어 손해율이 낮아진다"],"a":0,"e":"가정보다 많이 깨지면 **예실차**가 생기고 신계약에서 잡은 보험계약마진이 기대보다 빨리 줄어요.","deep":true}],"terms":[{"t":"법인보험대리점","d":"특정 보험사에 소속되지 않고 여러 보험사 상품을 함께 파는 판매 회사예요."},{"t":"수수료 환수","d":"계약이 일찍 해지되면 이미 지급한 모집수수료를 다시 돌려받는 것이에요."},{"t":"지급보증보험","d":"돈을 갚아야 할 사람이 못 갚을 때 보험회사가 대신 갚아주는 보험이에요. 설계사가 위촉될 때 가입하기도 해요."},{"t":"부당승환","d":"소비자에게 불리한데도 기존 보험을 해지시키고 비슷한 새 보험으로 갈아타게 하는 영업이에요."},{"t":"1200% 룰","d":"보험사가 설계사에게 계약 첫해에 줄 수 있는 수수료를 월 보험료의 12배 이내로 묶는 규칙이에요."}],"thread":{"id":"sales-channel","name":"판매채널과 수수료"},"jobs":["영업·채널","계리"],"sources":[{"name":"뉴스웍스","url":"https://www.newsworks.co.kr/news/articleView.html?idxno=856020"},{"name":"중앙이코노미뉴스","url":"https://www.joongangenews.com/news/articleView.html?idxno=553636"},{"name":"뉴스토마토","url":"https://newstomato.com/ReadNews.aspx?no=1315556"}],"brief":{"what":"10월 8일 금융위원회 국정감사에 대형 법인보험대리점 대표가 처음으로 일반 증인으로 나왔어요.","why":"소속 설계사 위촉계약에 계약이 초기에 해지되면 받은 수수료를 최대 120%까지 돌려받는 조항이 있었는데, 보험사가 보험대리점에 적용하는 환수율은 95~100%라서 차액의 행방이 문제가 됐어요.","so":"설계사가 환수금을 못 갚으면 회사는 지급보증보험으로 돈을 받고 설계사에게는 빚이 남아요. 초기 해지가 많은 채널은 **해지율 가정과 보험계약마진을 흔들 수 있어서** 판매 품질 관리가 중요해요."},"pre":["수수료 환수","법인보험대리점"]},{"id":"2026-10-31-11","date":"2026-10-31","tag":"자동차보험 · 손해율","title":"'8주룰' 한 달, 합의 재촉하면 신고하세요? 손보협회가 경상환자 피해 신고센터를 여는 이유","predict":{"q":"9월 10일 사고부터 가벼운 교통사고 환자가 8주 넘게 치료받으려면 치료 필요성 검토를 받게 됐어요. 한 달 뒤 손해보험협회가 내놓은 조치는 무엇이었을까요?","options":["보험사의 부당한 보상처리를 신고받는 센터를 연다","치료 필요성 검토를 중단하고 보험사 자율에 맡긴다","치료 필요성 검토 기간을 8주에서 6주로 줄인다"],"answer":0,"reveal":"10월 12일부터 **'자동차보험 경상환자 보상처리 피해 신고센터'**를 운영해요. 보험사가 새 절차를 핑계로 합의를 재촉하거나 지급보증을 마음대로 끊는 일을 막으려는 거예요."},"comic":{"title":"8주가 다가오면 생기는 일","panels":[{"caption":"가벼운 교통사고로 치료 중인 감자 가입자","bg":"hospital","chars":[{"who":"potato","mood":"worried","pose":"phone","say":"7주 안에 서류를 내야 한대요"}]},{"caption":"그런데 서류 안내도 없이 합의부터 하자는 연락이…","bg":"home","chars":[{"who":"insurer","mood":"happy","pose":"doc","say":"이쯤에서 합의하시죠?"},{"who":"potato","mood":"angry","pose":"stand","fx":"exclaim","say":"아직 치료 중인데요!"}]},{"caption":"손해보험협회가 신고센터를 열었어요","bg":"office","sign":"피해 신고 6가지 유형","chars":[{"who":"regulator","mood":"thinking","pose":"point","say":"합의 종용, 신고하세요"}]},{"caption":"계리사의 정리","bg":"meeting","board":"flat","chars":[{"who":"mango","mood":"happy","pose":"point","fx":"idea","say":"누수는 막고 필요한 치료는 지켜야 해요"}]}]},"figs":[{"type":"timeline","title":"경상환자 장기치료 검토 제도, 지금까지의 흐름","items":[{"when":"2026년 9월 2일","label":"금감원, 자동차보험 표준약관 개정과 안내 발표"},{"when":"2026년 9월 10일","label":"이날 이후 사고부터 8주 넘는 치료에 필요성 검토 적용"},{"when":"2026년 10월 8일","label":"손해보험협회, 보상처리 피해 신고센터 운영 발표","now":true},{"when":"2026년 10월 12일","label":"신고센터 운영 시작"},{"when":"2026년 10월 25일","label":"이후 보험기간이 시작되는 계약부터 경상환자 향후치료비 대신 실제 치료비 보장"}],"look":"9월 10일 사고부터 적용되고, 10월 12일 신고센터가 문을 열었어요."}],"numbers":[{"label":"적용 대상","value":"12~14급","note":"염좌·타박상 등 경상환자. 영유아·임산부는 제외"},{"label":"서류 제출 기한","value":"7주 이내","note":"사고일부터. 진단서·진료기록부 등"},{"label":"검토 결과 통보","value":"7일 이내","note":"자동차손해배상진흥원이 요청일부터"},{"label":"2025년 자동차보험 손익","value":"−7,080억 원","note":"보험손익 기준 적자"}],"points":["9월 10일 이후 사고로 다친 **상해등급 12~14급 경상환자**가 8주를 넘겨 치료받으려면, 사고일부터 7주 안에 진단서와 진료기록부 등을 내고 치료 필요성 검토를 받아야 해요.","손해보험협회는 10월 12일부터 **보상처리 피해 신고센터**를 열어 서류 안내 누락, 발급비 떠넘기기, 합의 종용, 지급보증 일방 중단 등 6가지 유형을 전화로 신고받기로 했어요.","7주 안에 신청했는데 심사가 늦어져 8주를 넘기면 그동안의 치료비는 보험사가 부담해요. 결과에 이의가 있으면 7일 안에 분쟁조정 위원회에 신청할 수 있어요."],"why":"자동차보험은 2025년 보험손익이 7,080억 원 적자일 만큼 수익성이 나빠졌고, 가벼운 부상의 **과잉 장기치료**가 보험금 누수의 원인으로 꼽혀 왔어요. 8주룰은 이 누수를 줄여 손해율을 낮추려는 제도예요. 하지만 보험사가 새 절차를 이용해 **정당한 치료까지 끊으면** 소비자 신뢰를 잃고 분쟁이 늘 수 있어요. 그래서 제도 시행 한 달 만에 신고센터가 생긴 거예요. 손해율 기사를 볼 때는 '보험금이 줄었다'는 숫자만 보지 말고, 그게 누수를 막아서인지 필요한 보상을 덜 해서인지 함께 따져보는 습관이 필요해요.","chain":["경상환자 과잉 장기치료로 보험금 누수","자동차보험 손익 적자 확대","9월 10일 사고부터 8주 초과 치료 필요성 검토","보험사의 합의 종용·지급보증 중단 우려","10월 12일 보상처리 피해 신고센터 운영","누수 차단과 정당한 보상의 균형이 손해율 개선의 질 결정"],"role":{"q":"당신은 손해보험사 보상팀 신입이에요. 선배가 말합니다. \"8주룰 생겼으니 7주차쯤 되면 합의 얘기부터 꺼내는 게 손해율 관리에 좋지 않아?\" 이 방식이 왜 위험한지 설명해보세요.","model":"치료가 끝나기 전에 합의를 재촉하는 것은 손해보험협회 신고센터가 받는 **피해 유형**에 그대로 해당한다. 단기적으로 보험금을 줄일 수는 있어도 민원과 분쟁이 늘고, 회사 신뢰가 떨어지며, 당국의 개선조치 대상이 될 수 있다. 8주룰의 취지는 정당한 치료는 보장하면서 **필요 없는 장기치료만 걸러내는 것**이다. 보상팀은 4주차·7주차 서류 안내를 빠짐없이 하고, 검토 결과와 이의제기 절차를 정확히 안내해 제도가 신뢰를 얻도록 해야 한다. 그래야 손해율 개선이 일시적이지 않고 오래 간다."},"summary":"가벼운 교통사고 환자가 8주 넘게 치료받으려면 심사를 받게 됐는데, 보험사가 이걸 핑계로 합의를 재촉하거나 보증을 끊을까 봐 손해보험협회가 피해 신고센터를 열었어.","interview":{"q":"자동차보험 경상환자 8주룰과 피해 신고센터 도입을 손해보험사 입장에서 어떻게 평가하나요?","guide":"결론부터: 손해율 개선에 꼭 필요한 제도지만, 신뢰를 지켜야 효과가 오래간다고 봐요.\n근거: 2025년 자동차보험 보험손익이 7,080억 원 적자였고, 9월 10일 사고부터 12~14급 경상환자의 8주 초과 치료에 필요성 검토가 생겼어요. 한 달 뒤 합의 종용 등 6가지 유형을 받는 신고센터가 문을 열었어요.\n관점: 보상·계리 관점에서 보험금 감소가 누수 차단 덕분인지 보상 축소 때문인지 구분해서 봐야 손해율 개선을 제대로 평가할 수 있어요.\n마무리: 서류 안내와 이의 절차를 정확히 지키는 보상 품질이 곧 회사 경쟁력이라고 정리해요."},"quiz":[{"q":"8주 넘는 치료에 필요성 검토를 받는 대상은?","o":["상해등급 1~11급 중상환자","상해등급 12~14급 경상환자와 영유아·임산부 전체","상해등급 12~14급 경상환자(영유아·임산부 제외)"],"a":2,"e":"염좌·타박상 등 **12~14급 경상환자**가 대상이고, 중상환자와 영유아·임산부는 빠져요."},{"q":"다음 중 신고센터의 신고 대상이 아닌 것은?","o":["다음 해 자동차보험료가 오른 것에 대한 불만","상해등급을 보험사가 임의로 결정","이의 신청 절차를 안내하지 않음"],"a":0,"e":"신고 대상은 서류 안내 누락, 발급비 부담, 합의 종용, 이의 안내 누락, 지급보증 중단, 상해등급 임의 결정의 **6가지**예요."},{"q":"8주룰 시행 뒤 자동차보험 손해율이 떨어졌다면, 계리사가 함께 확인해야 할 것은?","o":["보험설계사 수가 전년보다 늘었는지","감소가 누수 차단 때문인지 정당한 보상 축소 때문인지","자동차 판매 대수가 늘었는지"],"a":1,"e":"정당한 보상까지 줄인 개선은 **분쟁과 민원**으로 되돌아와 오래가지 않을 수 있어요.","deep":true}],"terms":[{"t":"경상환자","d":"염좌, 타박상처럼 가벼운 부상을 입은 환자예요. 자동차보험에서는 상해등급 12~14급을 말해요."},{"t":"상해등급","d":"자동차사고 부상의 정도를 1급(가장 무거움)부터 14급까지 나눈 기준이에요."},{"t":"지급보증","d":"보험사가 병원에 '이 환자의 치료비는 우리가 내겠다'고 약속하는 것이에요."},{"t":"향후치료비","d":"합의할 때 앞으로 받을 치료에 쓸 돈이라며 미리 주는 보험금이에요."},{"t":"손해율","d":"보험사가 받은 보험료 가운데 보험금으로 나간 돈의 비율이에요. 높을수록 보험사 수익이 나빠져요."}],"thread":{"id":"auto-loss","name":"자동차보험 손해율과 보험료"},"jobs":["보상·손해사정","계리"],"sources":[{"name":"한국보험신문","url":"https://www.insnews.co.kr/news/articleView.html?idxno=93228"},{"name":"한국보험신문","url":"https://www.insnews.co.kr/news/articleView.html?idxno=92593"}],"brief":{"what":"손해보험협회가 10월 12일부터 자동차보험 경상환자 보상처리 피해 신고센터를 운영해요.","why":"9월 10일 이후 사고부터 상해등급 12~14급 경상환자가 8주를 넘겨 치료받으려면 치료 필요성 검토를 받아야 하는데, 보험사가 새 절차를 핑계로 합의를 재촉하거나 지급보증을 마음대로 끊을 수 있어서예요.","so":"서류 안내 누락, 발급비 떠넘기기, 합의 종용, 지급보증 일방 중단 등 6가지 유형을 신고받아요. 과잉 장기치료를 줄이려는 제도지만 **정당한 치료까지 끊으면** 분쟁이 늘 수 있어요."},"pre":["경상환자","상해등급"]},{"id":"2026-10-31-12","date":"2026-10-31","tag":"인수합병","title":"삼성생명이 해외에서 2조 원을 빌린다? 30년 만기 신종자본증권에 담긴 '해외 확장' 신호","predict":{"q":"삼성생명이 15억 달러(약 2조 원) 한도의 30년 만기 해외 신종자본증권 발행을 결정했어요. 업계에서 가장 많이 나온 해석은 무엇이었을까요?","options":["지급여력비율이 권고치 아래로 내려가 급히 자본을 메우려는 것","해외 보험사 인수합병 자금을 미리 마련하는 것","보험금 지급이 늘어 생긴 적자를 메우려는 것"],"answer":1,"reveal":"회사는 **새 성장 동력과 미래 먹거리 확보**, 그리고 자본 건전성과 배당 안정성 유지를 이유로 들었어요. 업계는 **해외 보험사 인수합병 자금**을 미리 마련하는 것으로 해석했어요. 다만 인수 대상은 알려지지 않았어요."},"figs":[{"type":"timeline","title":"삼성생명 해외 진출의 큰 줄기","items":[{"when":"1997년","label":"국내 생보사 최초 해외 진출, 태국법인 설립"},{"when":"2021년","label":"영국 부동산 운용사 세빌스IM 지분 25% 인수"},{"when":"2023년","label":"프랑스 인프라 운용사 메리디암 지분 20% 인수"},{"when":"2025년","label":"유럽 대체투자 운용사 헤이핀 지분 3.96% 취득"},{"when":"2026년 10월 8일","label":"15억 달러 한도 30년 만기 해외 신종자본증권 발행 결정","now":true}],"look":"1997년 태국법인에서 시작해 2026년 15억 달러 자본증권 발행까지 왔어요."},{"type":"compare","title":"이번 발표로 알 수 있는 것과 아직 모르는 것","left":"발표된 내용","right":"아직 정해지지 않은 것","rows":[{"label":"규모","left":"15억 달러(약 2조 원) 한도","right":"최종 발행 금액"},{"label":"만기","left":"30년","right":"금리 조건"},{"label":"일정","left":"올해 안 마무리 목표","right":"신용등급과 투자설명회 결과"},{"label":"쓰임새","left":"성장 동력 확보, 자본·배당 안정","right":"구체적인 인수 대상"}],"note":"10월 8일 발표 시점 기준이에요.","look":"규모와 만기는 정해졌지만 인수 대상과 최종 발행 금액은 아직이에요."}],"numbers":[{"label":"발행 한도","value":"15억 달러","note":"약 2조 원"},{"label":"만기","value":"30년","note":"올해 안에 발행 마무리 방침"},{"label":"해외 보험 손익 비중 목표","value":"30%","note":"2030년까지. 자산운용 비중 목표는 32%"},{"label":"태국법인 상반기 순이익","value":"262억 원","note":"2026년 상반기"}],"points":["삼성생명은 10월 8일 **15억 달러(약 2조 원) 한도의 30년 만기 해외 신종자본증권** 발행을 결정했어요. 글로벌 신용평가사 등급을 받고 해외 기관투자자 대상 투자설명회를 거쳐 올해 안에 발행할 계획이에요.","회사는 새로운 성장 동력 확보와 함께 **해외 투자를 늘려도 자본 건전성과 배당을 안정적으로 유지**하려는 목적이라고 밝혔어요.","삼성생명은 2030년까지 손익에서 해외 보험 비중을 30%, 자산운용 비중을 32%로 높이는 목표를 세웠어요. 태국법인은 올해 상반기 262억 원, 중국 합작사는 약 1,618억 원의 순이익을 냈어요."],"why":"**신종자본증권**은 만기가 아주 길고 이자 지급을 미룰 수 있는 등 자본에 가까운 성격을 가진 채권이에요. 보험사는 이런 증권으로 가용자본을 늘려 지급여력비율을 지킬 수 있어요. 이번 발표가 눈길을 끈 건 '부족한 자본을 메우려는' 발행이 아니라 **'투자를 하고도 건전성과 배당을 지키려는'** 선제적 발행이라는 점이에요. 보험연구원은 2026년 보험료 성장률을 2.3%로 내다볼 만큼 국내 시장 성장이 둔해졌고, 큰 보험사일수록 해외에서 길을 찾고 있어요. 다만 자본증권은 이자 부담이 있고, 해외 인수는 그 나라의 위험과 회계·건전성 기준을 함께 떠안는 일이라 계리·리스크 쪽의 검토가 중요해요.","chain":["국내 보험 시장 성장 둔화","해외 보험·자산운용에서 성장 동력 모색","인수·투자에 큰돈이 들면 자본비율과 배당이 흔들릴 수 있음","30년 만기 신종자본증권으로 자본 선제 확보","해외 인수합병 자금 마련이라는 업계 해석","이자 부담과 해외 위험 관리가 새 과제"],"role":{"q":"당신은 생명보험사 리스크관리팀 신입이에요. 팀장님이 묻습니다. \"우리도 해외 보험사를 인수하려면 자본증권부터 찍어야 한다는데, 그냥 가진 돈으로 사면 안 되나?\" 미리 자본을 마련하는 이유를 설명해보세요.","model":"보험사가 가진 돈으로 큰 인수를 하면 그만큼 손실 흡수 여력이 줄고, 인수한 회사의 위험까지 더해져 **지급여력비율이 떨어질 수 있다**. 비율이 낮아지면 배당 같은 주주환원도 줄여야 할 수 있다. 그래서 장기 자본증권으로 가용자본을 먼저 늘려두면 인수 뒤에도 건전성과 배당을 안정적으로 유지할 수 있다. 다만 신종자본증권은 이자를 계속 내야 하므로, 인수로 얻을 이익이 **자본 조달 비용보다 큰지**와 해외 사업의 위험을 함께 따져봐야 한다."},"summary":"삼성생명이 해외에서 30년짜리로 최대 2조 원을 빌리기로 했는데, 자본처럼 쳐주는 채권이라 해외 보험사를 사들여도 회사 체력과 배당을 지키려는 준비로 보는 사람이 많아.","interview":{"q":"삼성생명이 15억 달러 규모의 해외 신종자본증권 발행을 결정했어요. 이 결정을 어떻게 보나요?","guide":"결론부터: 국내 성장이 둔해진 상황에서 해외 확장을 준비하면서도 건전성과 배당을 지키려는 선제적 결정으로 봐요.\n근거: 15억 달러(약 2조 원) 한도, 30년 만기이고, 2030년까지 해외 보험 손익 비중 30% 목표를 세웠어요. 태국법인은 상반기 262억 원의 순이익을 냈어요.\n관점: 리스크·계리 관점에서 자본증권의 이자 비용과 인수할 회사의 위험이 지급여력비율에 주는 영향을 함께 따져봐야 해요.\n마무리: 해외 인수의 성패는 사는 것보다 그 회사의 위험을 우리 기준으로 관리하는 능력에 달렸다고 정리해요."},"quiz":[{"q":"삼성생명이 결정한 해외 신종자본증권의 만기는?","o":["10년","20년","30년"],"a":2,"e":"만기 **30년**, 한도 15억 달러(약 2조 원)예요."},{"q":"회사가 밝힌 발행 목적에 들어가지 않는 것은?","o":["기존에 발행한 해외 채권의 만기 상환","새 성장 동력 확보","자본 건전성과 배당 안정 유지"],"a":0,"e":"회사는 성장 동력 확보와 **건전성·배당 안정**을 목적으로 들었어요."},{"q":"보험사가 자본증권으로 자본을 늘릴 때 함께 따져야 할 부담은?","o":["보험계약자에게 줄 보험금이 자동으로 줄어듦","자본으로 인정받아도 계속 내야 하는 이자 비용","해외 투자 수익이 확정적으로 보장됨"],"a":1,"e":"자본으로 인정받아도 **이자 비용**이 생기니, 투자로 얻을 이익이 조달 비용보다 커야 해요.","deep":true}],"terms":[{"t":"신종자본증권","d":"만기가 아주 길고 이자 지급을 미룰 수 있어서 채권이지만 자본에 가깝게 인정받는 증권이에요."},{"t":"가용자본","d":"보험사가 손실을 메우는 데 실제로 쓸 수 있는 자본이에요. 지급여력비율의 분자예요."},{"t":"지급여력비율","d":"보험사가 위험이 닥쳐도 보험금을 줄 수 있는 능력을 보여주는 건전성 지표예요. 지금 제도의 이름을 따 킥스 비율이라고도 불러요."},{"t":"투자설명회","d":"증권을 팔기 전에 투자자들을 만나 회사와 발행 조건을 설명하는 자리예요."}],"thread":{"id":"insurer-mna","name":"보험사 인수합병과 사업 확장"},"jobs":["리스크관리","계리"],"companies":["삼성생명"],"sources":[{"name":"아시아투데이","url":"https://www.asiatoday.co.kr/kn/view.php?key=20261008010002649"},{"name":"허프포스트코리아","url":"https://www.huffingtonpost.kr/article/261156"}],"brief":{"what":"삼성생명이 10월 8일 15억 달러(약 2조 원) 한도의 30년 만기 해외 신종자본증권 발행을 결정했어요.","why":"국내 시장 성장이 둔해져(보험연구원은 2026년 보험료 성장률을 2.3%로 전망) 큰 보험사일수록 해외에서 길을 찾고 있고, 업계는 해외 보험사 인수합병 자금을 미리 마련하는 것으로 해석했어요.","so":"자본에 가까운 증권이라 해외 투자를 늘려도 **자본 건전성과 배당을 안정적으로 유지**할 수 있지만, 이자 부담이 있고 인수 대상은 아직 알려지지 않았어요."},"pre":["신종자본증권","가용자본"]},{"id":"2026-10-31-13","date":"2026-10-31","tag":"감독·계리","title":"보험금은 통계로 예상하는 건데, 목표에 맞춰 늘리라고? 갱신보험 손해율에 칼 빼든 금감원","predict":{"q":"보험사가 갱신보험의 미래 손해율을 당국의 목표손해율보다 낮게 잡았어요. 금감원이 준비 중인 지침은 무엇을 하라고 했을까요?","options":["갱신 시점의 보험료 예상액만 낮춰 맞춘다","미래 보험금 지급 예상액을 줄여 목표손해율에 맞춘다","미래 보험금 지급 예상액을 늘려 목표손해율에 맞춘다"],"answer":2,"reveal":"금감원은 처음엔 갱신 시점 보험료 예상액만 조정하려 했지만, 계약마다 갱신 시점이 달라 목표를 맞추기 어려워 **보험금 지급 예상액까지 조정**하는 방안을 추진하고 있어요. 올해 12월 결산부터 적용하는 게 목표예요."},"comic":{"title":"손해율 70%의 마법","panels":[{"caption":"갱신보험의 미래 손해율을 낮게 잡으면","bg":"meeting","board":"up","chars":[{"who":"insurer","mood":"happy","pose":"point","fx":"sparkle","say":"손해율 70%면 이익이 쑥!"}]},{"caption":"금감원이 목표손해율을 정했어요","bg":"office","sign":"목표보다 낮으면 보험금 예상액 올리기","chars":[{"who":"regulator","mood":"thinking","pose":"doc","say":"마음대로 낮게 잡으면 안 돼요"}]},{"caption":"업계는 순서가 뒤바뀌었다고 반발해요","bg":"meeting","chars":[{"who":"insurer","mood":"angry","pose":"stand","fx":"exclaim","say":"목표로 거꾸로 계산하라고요?"},{"who":"mango","mood":"thinking","pose":"think","fx":"question"}]},{"caption":"망고 계리사의 정리","bg":"meeting","board":"flat","chars":[{"who":"mango","mood":"happy","pose":"point","fx":"idea","say":"가정의 근거를 통계로 보여야 해요"}]}]},"figs":[{"type":"compare","title":"갱신보험 손해율 가정, 무엇이 바뀌나","left":"지금까지","right":"금감원 추진 방안","rows":[{"label":"손해율 예상 기준","left":"보험사마다 달랐어요","right":"당국이 정한 목표손해율로 통일"},{"label":"예상이 목표보다 낮으면","left":"그대로 반영","right":"10년에 걸쳐 목표 수준에 닿도록 가정"},{"label":"조정 대상","left":"-","right":"보험료 예상액에 더해 보험금 지급 예상액까지"},{"label":"적용 시점","left":"-","right":"올해 12월 결산부터(목표)"}],"note":"실손보험은 빠져요. 한국경제 2026년 10월 12일 기사 기준이에요.","look":"보험사마다 달랐던 손해율 가정을 목표손해율로 통일하려 해요."},{"type":"bars","title":"기사 속 예시: 미래 보험료 1,000억 원일 때 보험금 예상액","unit":"억 원","items":[{"label":"통계로 예상한 보험금(손해율 70%)","value":700,"text":"700억 원"},{"label":"목표손해율 80%에 맞춘 보험금","value":800,"text":"800억 원","hi":true}],"note":"차이 100억 원만큼 보험부채가 늘고 보험계약마진은 줄어들 수 있어요.","look":"보험료 1,000억 원이면 보험금 예상액이 700억 원에서 800억 원이 돼요."}],"numbers":[{"label":"적용 목표","value":"12월 결산","note":"올해 결산부터 적용 추진"},{"label":"목표 도달 기간","value":"10년","note":"실제 손해율이 낮으면 10년에 걸쳐 목표까지 오른다고 가정"},{"label":"기사 속 예시 증가액","value":"+100억 원","note":"보험료 1,000억 원, 목표손해율 80%일 때"}],"points":["금감원이 **실손보험을 뺀 갱신보험**의 손해율 산정 기준을 통일하는 지침을 준비하고 있어요. 보험사가 예상한 손해율이 당국이 정한 목표손해율보다 낮으면, 미래 보험금 지급 예상액을 늘려 목표에 맞추게 하는 방식이에요.","새 국제회계기준에서는 미래 손해율을 낮게 잡을수록 보험부채가 줄고 미래 이익이 커 보일 수 있어서, 당국은 이를 **이익 부풀리기**로 보고 막으려는 거예요.","업계는 과거 통계로 보험금을 예상하는 게 순서인데 **목표를 먼저 정하고 거꾸로 계산**하게 한다며 반발해요. 예를 들어 $$\\frac{700}{1000}\\times 100=70\\%$$인 손해율을 80%로 맞추려면 보험금 예상액을 800억 원으로 늘려야 해요."],"why":"새 국제회계기준에서 손해율 같은 **계리가정** 하나가 보험부채와 보험계약마진, 곧 회사의 미래 이익을 움직여요. 갱신보험은 보험사마다 예상 기준이 달라서 같은 상품도 회사에 따라 이익이 다르게 보일 수 있었어요. 이번 지침은 당국과 업계가 '통계를 믿을지, 목표를 믿을지'를 두고 부딪치는 장면이에요. 금감원이 올해 1월 낸 계리가정 3대 세부원칙은 충분한 경험통계가 있으면 그걸 근거로 하라고 했기 때문에 서로 어긋난다는 지적도 나와요. 계리사라면 **가정의 근거를 통계로 설명할 수 있어야** 이런 일률적인 규제를 피할 수 있다는 점을 기억해두세요.","chain":["보험사마다 다른 갱신보험 손해율 예상","미래 손해율을 낮게 잡으면 이익이 커 보임","금감원, 목표손해율로 기준 통일 추진","보험금 지급 예상액까지 늘리도록 조정","보험부채 증가, 보험계약마진 감소 가능","업계 '통계 대신 목표로 역산' 반발"],"role":{"q":"당신은 손해보험사 계리팀 신입이에요. 재무팀장님이 묻습니다. \"우리 갱신보험 손해율이 목표보다 낮은 건 손해율 관리를 잘해서인데, 왜 보험금 예상액을 억지로 올려야 하죠?\" 금감원의 논리와 회사가 준비할 일을 설명해보세요.","model":"금감원은 미래 손해율을 낮게 잡을수록 보험부채가 줄고 이익이 커 보이는 구조를 문제로 본다. 보험사마다 예상 기준이 달라 **자의적으로 낮게 잡을 여지**가 있었기 때문에, 목표손해율보다 낮으면 10년에 걸쳐 목표 수준에 닿는다고 가정하게 하려는 것이다. 다만 회사가 실제로 손해율을 잘 관리했다면, 그 근거를 **담보별 경험통계와 추세 분석**으로 정리해 감독당국에 설명하는 것이 먼저다. 12월 결산에 적용되면 보험부채가 늘고 보험계약마진이 줄 수 있으니, 영향 규모를 미리 계산해 경영진에게 보고하는 것도 계리팀의 일이다."},"summary":"보험사가 앞으로 나갈 보험금을 적게 예상하면 이익이 커 보이니까, 금감원이 갱신보험 손해율에 목표를 정해서 그보다 낮으면 보험금 예상액을 늘리라고 하려는 거야. 업계는 통계 말고 목표로 거꾸로 계산하는 건 이상하다고 반발해.","interview":{"q":"금감원이 갱신보험 손해율을 목표손해율에 맞추도록 하는 지침을 추진하고 있습니다. 계리 관점에서 어떻게 보나요?","guide":"결론부터: 이익 부풀리기를 막으려는 취지는 공감하지만, 가정은 통계 근거가 우선이어야 한다고 봐요.\n근거: 금감원은 실손을 뺀 갱신보험에서 예상 손해율이 목표보다 낮으면 보험금 예상액을 늘려 맞추게 하고, 12월 결산부터 적용하려 해요. 기사 예시처럼 보험료 1,000억 원에 예상 보험금 700억 원이면 목표 80%에 맞추려고 100억 원을 늘려야 해요.\n관점: 계리사는 담보별 경험통계로 가정의 근거를 보여줄 수 있어야 하고, 보험부채와 보험계약마진에 주는 영향도 미리 계산해야 해요.\n마무리: 당국과 회사가 같은 통계를 보고 이야기할 수 있게 가정 산출 과정을 투명하게 만드는 게 계리의 역할이라고 정리해요."},"quiz":[{"q":"새 국제회계기준에서 미래 손해율을 낮게 잡으면 어떤 일이 생길 수 있나요?","o":["보험부채가 줄고 미래 이익이 커 보일 수 있다","보험부채가 늘고 미래 이익이 작아 보일 수 있다","보험부채는 줄지만 미래 이익도 함께 줄어 보인다"],"a":0,"e":"미래 보험금 예상액이 줄어 **보험부채가 작아지고** 미래 이익이 커 보일 수 있어요."},{"q":"기사 예시에서 미래 보험료 1,000억 원, 목표손해율 80%라면 보험금 예상액은 얼마로 맞춰야 하나요?","o":["900억 원","700억 원","800억 원"],"a":2,"e":"$$1000\\times 80\\%=800$$억 원이에요. 통계로 예상한 700억 원보다 100억 원 늘어요."},{"q":"업계가 이 지침을 비판하는 핵심 이유는?","o":["갱신보험의 보험료를 당국이 직접 정하게 되어서","목표손해율에서 거꾸로 보험금을 계산하게 해서","실손보험까지 포함해 손해율을 통일해서"],"a":1,"e":"보통은 과거 지급 실적으로 미래 보험금을 예상하는데, 이번 방식은 **목표손해율에서 역산**한다는 점이 비판받아요. 실손보험은 대상에서 빠져요.","deep":true}],"terms":[{"t":"목표손해율","d":"보험료를 조정해서 도달하려는 손해율이에요. 손실계약은 보통 100%를 기준으로 해요."},{"t":"계리가정","d":"보험료와 보험부채를 계산할 때 쓰는 예상 손해율, 해지율, 사업비율 같은 전제예요."},{"t":"갱신보험","d":"일정 기간이 지나면 그때의 손해율 등을 반영해 보험료를 다시 정하는 보험이에요."},{"t":"보험계약마진","d":"보험계약에서 앞으로 나눠서 이익으로 인식할, 아직 실현되지 않은 이익이에요."},{"t":"손해율","d":"보험사가 받은 보험료 가운데 보험금으로 나간 돈의 비율이에요. 높을수록 보험사 수익이 나빠져요."}],"thread":{"id":"actuarial-supervision","name":"계리감독 강화"},"jobs":["계리","상품개발","리스크관리"],"sources":[{"name":"한국경제","url":"https://www.hankyung.com/article/2026101269081"}],"brief":{"what":"금감원이 실손보험을 뺀 갱신보험에서 예상 손해율이 당국의 목표손해율보다 낮으면, 미래 보험금 지급 예상액을 늘려 맞추게 하는 지침을 준비하고 있어요.","why":"새 국제회계기준에서는 미래 손해율을 낮게 잡을수록 보험부채가 줄고 미래 이익이 커 보일 수 있어서, 당국이 이를 이익 부풀리기로 보고 막으려는 거예요.","so":"올해 12월 결산부터 적용하려는데, 업계는 통계로 예상하는 게 순서인데 **목표를 먼저 정하고 거꾸로 계산**하게 한다며 반발해요."},"pre":["목표손해율","계리가정"]},{"id":"2026-10-31-14","date":"2026-10-31","tag":"판매채널","title":"보험 광고 규정 위반 4만 7천 건, 그런데 제재금은 10건? '걸리면 지우면 그만'의 함정","predict":{"q":"2022년부터 2026년 상반기까지 손해보험협회 신고센터에서 확인된 보험 광고 규정 위반은 4만 7,078건이에요. 이 가운데 제재금이 부과된 건 몇 건일까요?","options":["46건","10건","210건"],"answer":1,"reveal":"제재금은 **단 10건**이었어요. 70.9%인 3만 3,367건은 게시물을 지우거나 고치는 시정조치로 끝났어요."},"comic":{"title":"지우면 그만?","panels":[{"caption":"블로그에 보험 광고를 올린 설계사","bg":"home","chars":[{"who":"planner","mood":"happy","pose":"phone","say":"심의는 나중에, 일단 올리자"}]},{"caption":"신고센터에 걸렸지만 대부분 삭제·수정으로 끝나요","bg":"office","sign":"시정조치만 70.9%","chars":[{"who":"planner","mood":"happy","pose":"shrug","say":"지우면 그만이죠"}]},{"caption":"국정감사에서 나온 지적","bg":"focus","chars":[{"who":"regulator","mood":"angry","pose":"point","fx":"exclaim","bubble":"shout","say":"반복 위반엔 제재를!"}]},{"caption":"망고 계리사의 정리","bg":"meeting","board":"flat","chars":[{"who":"mango","mood":"thinking","pose":"doc","fx":"idea","say":"잘못 판 계약은 민원으로 돌아와요"}]}]},"figs":[{"type":"bars","title":"연도별 보험 광고 심의 규정 위반 건수","unit":"건","items":[{"label":"2022년","value":3467,"text":"3,467건"},{"label":"2023년","value":25271,"text":"2만 5,271건","hi":true},{"label":"2024년","value":16461,"text":"1만 6,461건"},{"label":"2025년","value":1567,"text":"1,567건"},{"label":"2026년 상반기","value":312,"text":"312건"}],"note":"손해보험협회 과장광고신고센터 기준이에요.","look":"2023년 2만 5,271건으로 가장 많고 2026년 상반기는 312건이에요."},{"type":"split","title":"위반이 나온 매체","total":"4만 7,078건","items":[{"label":"블로그","value":39109,"text":"3만 9,109건"},{"label":"유튜브 등","value":4943,"text":"4,943건"},{"label":"기타(인스타그램·페이스북·지식인 등)","value":3026,"text":"3,026건"}],"look":"블로그 3만 9,109건이 4만 7,078건 가운데 대부분을 차지해요."}],"numbers":[{"label":"광고 규정 위반","value":"4만 7,078건","note":"2022년~2026년 상반기"},{"label":"심의를 안 받은 광고","value":"61.4%","note":"2만 8,918건"},{"label":"시정조치로만 끝남","value":"70.9%","note":"3만 3,367건(삭제·수정)"},{"label":"제재금 부과","value":"10건","note":"2025년에는 0건"}],"points":["박성훈 의원이 금융당국에서 받은 자료에 따르면 손해보험협회 신고센터에서 확인된 보험 광고 심의 규정 위반이 4년 반 동안 **4만 7,078건**이었어요. 그중 61.4%는 사전 심의를 아예 받지 않은 광고였고, 매체는 블로그가 3만 9,109건으로 가장 많았어요.","그런데 70.9%는 게시물 삭제·수정 같은 시정조치로 끝났고, **제재금은 10건**뿐이었어요. 금융소비자보호법 위반으로 금융위원회가 과태료를 매긴 것도 유튜브 광고에서 필수 기재사항을 빠뜨린 한 보험대리점(10억 원) 1건이에요.","의원은 이렇게 끝나면 '걸리면 지우면 그만'이라는 신호를 줄 수 있다며 **반복·중대 위반에는 실효성 있는 제재**가 필요하다고 지적했어요."],"why":"보험 광고는 소비자가 상품을 처음 만나는 입구예요. 온라인 광고는 올리고 지우고 다시 올리기가 쉬워서 시정조치만으로는 **상습 위반**을 막기 어려워요. 10월 1일 홈쇼핑 광고 이슈처럼, 광고가 과장되면 불완전판매와 해지, 민원으로 이어져 결국 회사의 비용과 신뢰를 갉아먹어요. 상품개발 직무라면 내가 만든 상품이 **어떤 말로 팔리는지**까지 신경 써야 하고, 뉴스를 볼 때는 위반 건수보다 '실제로 제재가 얼마나 따랐는가'를 함께 보는 습관이 필요해요.","chain":["블로그·유튜브 등 온라인 보험 광고 증가","사전 심의 없이 올리는 광고 많음","적발돼도 대부분 삭제·수정으로 끝","'지우면 그만' 신호로 상습 위반 우려","국정감사에서 실효성 있는 제재 요구","광고 단계부터 소비자보호 강화 압력"],"role":{"q":"당신은 보험사 상품개발팀 신입이에요. 새 상품 출시 회의에서 마케팅 담당자가 말합니다. \"대리점 블로그 광고는 걸리면 지우면 되니까 문구는 좀 세게 가도 괜찮아요.\" 이 생각의 위험을 설명해보세요.","model":"4년 반 동안 광고 규정 위반이 4만 7,078건이었고 대부분 시정조치로 끝났지만, 국정감사에서 **반복·중대 위반에 실효성 있는 제재**가 필요하다는 지적이 나왔다. 실제로 필수 기재사항을 빠뜨린 유튜브 광고로 과태료 10억 원을 받은 대리점도 있다. 무엇보다 과장 광고로 들어온 고객은 기대와 실제 보장이 달라 **해지와 민원**으로 이어지기 쉽고, 이는 상품의 유지율과 수익성을 해친다. 상품개발팀은 출시 단계에서 오해를 부를 만한 표현을 미리 정리한 광고 지침을 대리점과 함께 마련하는 게 안전하다."},"summary":"보험 광고가 규칙을 어긴 게 4만 7천 건 넘게 걸렸는데, 대부분 글만 지우고 끝나서 돈으로 제재받은 건 10건뿐이었어. 국회에서 이러면 '지우면 그만'이 된다고 따졌어.","interview":{"q":"온라인 보험 광고 위반이 4만 건 넘게 적발됐지만 제재는 거의 없었습니다. 보험사는 어떻게 대응해야 할까요?","guide":"결론부터: 제재가 약하더라도 보험사가 먼저 광고 관리를 강화해야 장기적으로 이득이라고 봐요.\n근거: 2022년~2026년 상반기 위반 4만 7,078건 중 61.4%가 미심의 광고였고, 70.9%가 삭제·수정으로 끝났으며 제재금은 10건뿐이었어요.\n관점: 상품개발 관점에서 과장 광고로 들어온 계약은 기대와 실제 보장이 달라 해지와 민원으로 이어지기 쉬워, 상품의 유지율과 손익 가정을 흔들 수 있어요.\n마무리: 출시 때 광고 지침을 함께 만들고 대리점 광고까지 점검하는 것이 소비자 신뢰와 수익성을 지키는 길이라고 정리해요."},"quiz":[{"q":"보험 광고 규정 위반 4만 7,078건 가운데 가장 많은 유형은?","o":["필수 기재사항을 빠뜨린 광고","심의 받은 내용과 다르게 바꾼 광고","사전 심의를 받지 않은 광고"],"a":2,"e":"**미심의 광고**가 2만 8,918건으로 61.4%를 차지했어요."},{"q":"위반이 가장 많이 나온 매체는?","o":["블로그","유튜브 등","인스타그램·페이스북 등"],"a":0,"e":"블로그가 **3만 9,109건**으로 가장 많았어요."},{"q":"온라인 광고 위반을 시정조치만으로 막기 어려운 이유로 가장 알맞은 것은?","o":["온라인 광고에는 사전 심의 제도 자체가 없어서","게시·삭제·재게시가 쉬워 상습 위반이 생기기 쉬워서","시정조치를 받은 광고는 다시 올릴 수 없어서"],"a":1,"e":"지우고 다시 올리기 쉬워서 **'걸리면 지우면 그만'**이 될 수 있어요.","deep":true}],"terms":[{"t":"광고 심의","d":"보험 광고를 내기 전에 협회 등이 과장이나 누락이 없는지 미리 검토하는 절차예요."},{"t":"시정조치","d":"규정을 어긴 광고를 지우거나 고치게 하는 조치예요. 돈으로 내는 제재는 아니에요."},{"t":"제재금","d":"협회 자율규제에서 규정을 어긴 회사에 물리는 돈이에요."},{"t":"금융소비자보호법","d":"금융상품을 팔 때 설명, 광고 등에서 지켜야 할 소비자 보호 규칙을 정한 법이에요."},{"t":"자율규제","d":"법으로 정한 규제 대신 업계 협회가 스스로 기준을 만들고 심의해서 지키는 방식이에요."}],"thread":{"id":"sales-channel","name":"판매채널과 수수료"},"jobs":["영업·채널","상품개발"],"sources":[{"name":"아시아경제","url":"https://view.asiae.co.kr/article/2026101210283170568"}],"brief":{"what":"2022년부터 2026년 상반기까지 손해보험협회 신고센터에서 확인된 보험 광고 규정 위반은 4만 7,078건인데, 제재금이 부과된 건 10건뿐이었어요.","why":"블로그 같은 온라인 광고는 올리고 지우고 다시 올리기 쉬운데, 위반의 70.9%가 게시물 삭제·수정 같은 시정조치로 끝났어요.","so":"\"걸리면 지우면 그만\"이라는 신호를 줄 수 있어서 **반복·중대 위반에는 실효성 있는 제재**가 필요하다는 지적이 나왔어요. 상품개발은 만든 상품이 어떤 말로 팔리는지까지 살펴야 해요."},"pre":["광고 심의","시정조치"]}]);
